window.KLIMA_SCENES={"title":"Argumentatlas zum Gespräch mit Reto Knutti","version":3,"source":{"transcript":"KI-Multimedia-Tool_Transkript_28-10-2026.docx (vom Nutzer bereitgestellte Arbeitsfassung)","timing":"Offizielle SRF-Untertitel (SWISS TXT), VTT; Zeitmarken am 28.10.2026 abgeglichen","subtitleUrl":"https://subtitles.eai-general.aws.srf.ch/srf/f5f60904-b095-4408-a418-09671868cc2a/episode/de/vod/vod.vtt","duration":3625.6,"scope":"Alle im Gespräch erkennbaren eigenständigen Begründungsschritte, Einwände, Gegenargumente und argumentativ relevanten Präzisierungen. Wiederholungen werden als Wiederaufnahmen ausgewiesen; Begrüssung, Teasermontage und Programmhinweise bilden keine zusätzlichen Argumente. Die Einteilung und Rekonstruktion sind didaktische Interpretationen, keine wörtlichen Zitate und keine Bestätigung von Sachbehauptungen.","framework":"Schlussfolgerungstypen_und_Fehlschluesse_Handbuch.pdf, Oktober 2026, 14 Seiten; alle 164 Einträge als Referenz erfasst."},"scenes":[{"title":"Auftakt: Aus Krisensymptomen wird eine Handlungsfrage","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch","claim":"Die Diskrepanz zwischen Klimafolgen und Handeln verlangt eine Erklärung.","reason":"Gletscherschmelze, Wassermangel und berichtete Todesfälle stehen geringem Handeln gegenüber.","type":"Abduktion (Schluss auf die beste Erklärung)","id":"A001","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Problemaufriss","legacyFamily":"Problemaufriss / Diskurskritik","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1}],"implicitPremise":"Wer starke Schäden erwartet und dennoch wenig Handlung beobachtet, benötigt eine Erklärung für diese Differenz.","assessment":"Der Einstieg formuliert ein Erklärungsproblem, noch keinen eigenständigen Beweis für politische Untätigkeit. Abduktion ist erst der nachfolgende Suchemodus.","fallacyChecks":[{"id":"VI-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Frage wäre geladen, falls sie ohne Beleg jede relevante bereits erfolgte Handlung ausschlösse.","page":8}],"verification":"Konkretisiere Zeitraum und Massstab für die behauptete Handlungslücke.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Düsternis allein erklärt die geringe Aufmerksamkeit nicht.","reason":"Kriege und geopolitische Spannungen interessieren das Publikum trotz ihres düsteren Charakters.","type":"Dialektischer Schluss · Deduktion","id":"A002","family":"Dialektischer Schluss","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-01","page":1}],"implicitPremise":"Wenn Düsternis allein geringe Aufmerksamkeit verursachte, müssten vergleichbar düstere Kriegsthemen ebenfalls wenig Aufmerksamkeit finden.","assessment":"Das Gegenbeispiel begrenzt die Alleinerklärung; es zeigt nicht, dass negative Emotionen überhaupt keinen Einfluss haben.","fallacyChecks":[{"id":"VIII-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Unterschiedliche Aktualität, Nähe oder Dramaturgie könnten den Vergleich verzerren.","page":11}],"verification":"Vergleiche Themen unter ähnlichen Bedingungen; formales Modus tollens gilt nur bei der ergänzten starken Wenn-Prämisse.","formalRule":{"id":"II-02","page":3,"scope":"Nur unter ergänzter starker Wenn-Prämisse","explanation":"P = Düsternis allein erklärt geringe Aufmerksamkeit; Q = vergleichbare düstere Kriegssendungen erhalten ebenfalls geringe Aufmerksamkeit. Ergänzt wird P → Q; beobachtet wird nicht Q; dann folgt nicht P. Die empirische Vergleichbarkeit ist gesondert zu prüfen."},"role":"Argument der sprechenden Person"}}],"questions":["Welche Prämissen stecken in der Formulierung «wenig bis nichts»?","Widerlegt das Kriegsbeispiel jede mögliche Rolle negativer Gefühle?"],"teacher":"Der Vorspann 00:00–00:32 montiert spätere Aussagen und enthält keine zusätzlichen selbstständigen Argumente. Der Vergleich zeigt höchstens, dass Düsternis keine hinreichende Erklärung ist. Die Folgenzahlen sind Gesprächsangaben, keine hier geprüften Fakten.","start":32.479,"id":"s01","end":90.4,"duration":57.921,"openingCueStart":32.479},{"title":"Debattenmüdigkeit und Verzichtsrahmung","theme":"Kommunikation","arguments":[{"speaker":"Knutti","claim":"Langjährige Klimakommunikation kann Aufmerksamkeit abnutzen.","reason":"Das Thema wurde über Jahre stark kommuniziert; inzwischen konkurrieren andere Themen darum.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A003","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausalerklärungsversuch","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Lange Exposition und konkurrierende Themen können Aufmerksamkeit gegenüber einem vertrauten Thema reduzieren.","assessment":"Eine plausible Ursachenhypothese wird angeboten, keine experimentell isolierte Ursache. Knuttis Wahrscheinlichkeitsvorbehalt passt zur abduktiven Stärke.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der Fehler entstünde erst, wenn Abnutzung als einzige Erklärung der Publikumsreaktion behandelt würde.","page":11}],"verification":"Suche Aufmerksamkeitsdaten sowie Alternativerklärungen durch Themenkonkurrenz und politische Einstellungen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine reine Verzichts- und Kostenrahmung erschwert Zustimmung.","reason":"Wenn Klimaschutz als Verbotskatalog erscheint, wenden sich Menschen davon ab.","type":"Kausaler Schluss · Defeasibles (aufhebbares) Schliessen","id":"A004","family":"Kausaler Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-09","page":2}],"implicitPremise":"Menschen meiden eher eine Botschaft, die sie ausschliesslich als persönlichen Verlust erleben.","assessment":"Die Wirkung einer Verzichtsrahmung ist eine aufhebbare Verhaltenshypothese, kein notwendiger Mechanismus bei jedem Publikum.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Einzelne Abwehrreaktionen tragen keine Aussage über alle Menschen und Kommunikationssituationen.","page":9}],"verification":"Bestimme Zielgruppe und Vergleichsrahmung; prüfe auch erfolgreiche Kommunikation über Pflichten.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Klimaschutz sollte als Gestaltung einer erfolgreichen Zukunft vermittelt werden.","reason":"Eine positive gemeinsame Perspektive bietet einen anderen Zugang als der Verlustkatalog.","type":"Praktischer Schluss","id":"A005","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wenn eine Kommunikationsweise ein legitimes Ziel besser fördert und keine schwereren Nachteile erzeugt, sollte man sie bevorzugen.","assessment":"Die positive Rahmung wird als Mittel zur Beteiligung empfohlen. Die Wertprämisse über das Kommunikationsziel ist zu ergänzen.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus besserer Wirkung allein folgt ohne Ziel- und Wahrhaftigkeitsnorm keine Pflicht zu dieser Rahmung.","page":12}],"verification":"Ergänze, dass die Darstellung wahrheitsgemäss bleiben und reale Belastungen sichtbar machen muss.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Rekonstruiere die Kausalkette zwischen Rahmung und Abwendung.","Welche Beobachtung könnte diese Erklärung widerlegen?"],"teacher":"Knutti formuliert anfangs vorsichtig: «wahrscheinlich». Rahmung ist eine Erklärungshypothese; aus ihrer Plausibilität folgt noch keine nachgewiesene Wirkung.","start":90.4,"id":"s02","end":128.28,"duration":37.88,"openingCueStart":90.4},{"title":"Werte hinterfragen, ohne nur Verzicht zu predigen","theme":"Kommunikation","arguments":[{"speaker":"Bleisch","claim":"Wirtschaft und Werte dürfen in einer positiven Erzählung nicht ausgeblendet werden.","reason":"Klimaschutz betrifft auch Verzicht und die Frage, was neben Geld zählt.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A006","family":"Praktischer Schluss","legacyType":"Normatives Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine angemessene Transformationsdebatte soll relevante Kosten und Wertkonflikte nicht zugunsten positiver Wirkung verschweigen.","assessment":"Bleisch ergänzt einen normativen Vollständigkeitsanspruch; dies ist ein sachlicher Einwand gegen einseitiges Framing.","fallacyChecks":[{"id":"V-23","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Strohmann läge vor, falls Knutti fälschlich die Leugnung jedes Verzichts zugeschrieben würde.","page":8}],"verification":"Prüfe seinen einschränkenden Ausdruck «nicht nur» und formuliere beide Positionen in ihrer stärksten Fassung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Wirtschaft und Werte müssen tatsächlich hinterfragt werden.","reason":"Natur und Biodiversität besitzen einen zu berücksichtigenden Wert.","type":"Praktischer Schluss","id":"A007","family":"Praktischer Schluss","legacyType":"Normatives Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Gesellschaftliche Entscheidungen sollen Natur- und Biodiversitätswerte neben monetären Zielen berücksichtigen.","assessment":"Die Schlussfolgerung beruht auf einem ausdrücklich wertenden Ausgangspunkt. Deshalb ist der praktische Schluss nicht allein wegen seines Sollens fehlerhaft.","fallacyChecks":[{"id":"IX-01","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Wertprämisse wird genannt; ein blosser Übergang von Tatsachen zu einer Norm ist hier nicht nachgewiesen.","page":12}],"verification":"Kläre, wie diese Werte begründet und bei Konflikten gewichtet werden sollen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Problembewusstsein allein ersetzt keine tragfähige Transformationsperspektive.","reason":"Menschen sollen für einen Veränderungsprozess gewonnen werden; eine reine Untergangserzählung leistet das nicht.","type":"Praktischer Schluss · Kausaler Schluss","id":"A008","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Für wirksame Beteiligung genügt Problemerkennung nicht; es braucht erreichbare Handlungsmöglichkeiten.","assessment":"Ein notwendiges Element einer Kommunikationsstrategie wird ergänzt. Nicht behauptet werden sollte, positive Perspektiven seien allein hinreichend.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Handlungsperspektiven als notwendige Hilfe dürfen nicht zu einer Erfolgsgarantie erklärt werden.","page":6}],"verification":"Formuliere Bedingungen, unter denen Angebote tatsächlich zugänglich und wirksam sind.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Widersprechen sich die beiden Positionen oder setzen sie unterschiedliche Schwerpunkte?","Trenne die Frage nach der Berechtigung einer Norm von der Frage ihrer kommunikativen Wirkung."],"teacher":"Knutti bestreitet nicht jeden Verzicht. Seine Einschränkung «nicht nur» ist zentral; eine Rekonstruktion als völlige Ablehnung moralischer Fragen wäre ein Strohmann.","start":128.28,"id":"s03","end":162.04,"duration":33.76,"openingCueStart":128.28},{"title":"Immer schon Klimawandel? Grenzen einer historischen Analogie","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch, als Einwand","claim":"Das Ausbleiben eines Weltuntergangs könnte die Alarmrahmung fragwürdig machen.","reason":"Das 1,5-Grad-Ziel wird im Gespräch als verfehlt dargestellt, während die Welt fortbesteht.","type":"Dialektischer Schluss","id":"A009","family":"Dialektischer Schluss","legacyType":"Rahmungskritik","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine dramatische Rahmung muss an den tatsächlich behaupteten Folgen geprüft werden, nicht allein am Fortbestand der Welt.","assessment":"Der Einwand testet die Untergangssprache. Dass die Welt fortbesteht, widerlegt weder schwere Schäden noch ein verfehltes Langfristziel.","fallacyChecks":[{"id":"VI-03","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Gegenüberstellung «Weltuntergang oder kein relevantes Problem» würde abgestufte Schäden ausblenden.","page":8}],"verification":"Trenne rhetorische Übertreibung, ein einzelnes warmes Jahr und das langfristige Pariser Temperaturziel.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Bleisch, als Einwand","claim":"Anpassung könnte eine Alternative zur Alarmhaltung sein.","reason":"Die Erde veränderte sich früher ebenfalls und Menschen passten sich an.","type":"Analogieschluss","id":"A010","family":"Analogieschluss","legacyType":"Historische Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2}],"implicitPremise":"Wenn Anpassung früher unter relevant ähnlichen Bedingungen gelang, könnte sie auch heute möglich sein.","assessment":"Der Schluss beruht auf einer historischen Ähnlichkeit. Seine Stärke hängt von Tempo, Bevölkerungsgrösse und gesellschaftlicher Verwundbarkeit ab.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Analogie scheitert, wenn gerade die für Anpassung entscheidenden Bedingungen verschieden sind.","page":12}],"verification":"Vergleiche Veränderungsraten, Anpassungsdauer und betroffene Versorgungssysteme.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Frühere Klimaveränderungen erlauben keine beruhigende Gleichsetzung mit der heutigen Lage.","reason":"Die gegenwärtige Veränderung erfolgt laut Gespräch viel schneller als frühere Veränderungen.","type":"Dialektischer Schluss · Kausaler Schluss","id":"A011","family":"Dialektischer Schluss","legacyType":"Analogiebegrenzung","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-06","page":2}],"implicitPremise":"Unterschiede in relevanten Anpassungsbedingungen schwächen die Übertragung früherer Erfolge.","assessment":"Knutti bestreitet nicht frühere Veränderung, sondern die Gleichheit der Bedingungen. Das begrenzt eine Analogie, beweist aber noch kein vollständiges Anpassungsversagen.","fallacyChecks":[{"id":"VIII-07","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Der Einwand richtet sich gegen die historische Gleichsetzung von A010.","page":12}],"verification":"Zeige, welche konkrete Anpassungsleistung durch den höheren Zeitdruck erschwert wird.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Heutige Anpassung ist strukturell schwieriger.","reason":"Eine grosse Bevölkerung muss ernährt werden und ein stark angepasstes Wirtschaftssystem ist betroffen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A012","family":"Kausaler Schluss","legacyType":"Kausales Argument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Je stärker Versorgung und Infrastruktur an stabile Bedingungen gebunden sind, desto aufwendiger ist rasche Anpassung.","assessment":"Bevölkerungs- und Systemkomplexität werden als Verstärker einer künftigen Anpassungslast angeführt.","fallacyChecks":[{"id":"VIII-06","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Mehrere Faktoren werden ausdrücklich genannt; eine einzige universelle Ursache wird hier nicht bewiesen oder benötigt.","page":11}],"verification":"Quantifiziere die Verwundbarkeit einzelner Sektoren und berücksichtige neue Anpassungskapazitäten.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche relevanten Unterschiede entkräften die Analogie?","Warum folgt aus «kein Weltuntergang» nicht «keine gravierenden Schäden»?"],"teacher":"Knutti bestreitet die frühere Veränderung nicht, sondern die Übertragbarkeit. Die 1,5-Grad-Aussage muss begrifflich zwischen Einzeljahr, langfristigem Mittel und politischem Ziel unterschieden werden.","start":162.04,"id":"s04","end":243.96,"duration":81.92,"openingCueStart":162.04},{"title":"2,8 Grad und nichtlineare Schäden","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch","claim":"Eine globale Temperaturzahl ist ohne Folgenbeschreibung kommunikativ unzureichend.","reason":"Sie kann die konkrete Bedeutung von 2,8 Grad nicht einordnen.","type":"Dialektischer Schluss","id":"A013","family":"Dialektischer Schluss","legacyType":"Verständlichkeitsargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Für ein Folgenurteil müssen Messzahl, Bezug und betroffene Güter verständlich sein.","assessment":"Die Nachfrage benennt eine Informationslücke. Persönliches Nichtverstehen wird nicht als Widerlegung der Klimaprojektion verwendet.","fallacyChecks":[{"id":"VI-20","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Bleisch erklärt die Zahl nicht deshalb für falsch, weil sie sie nicht anschaulich versteht.","page":9}],"verification":"Ergänze Referenzperiode, Szenario und konkrete lokale Folgen, statt die Zahl allein zu wiederholen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Weitere Erwärmung darf nicht als gleichmässiger Schadenszuwachs gedacht werden.","reason":"Anpassungsmöglichkeiten sind begrenzt; zusätzliche Erwärmung trifft auf diese Grenzen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A014","family":"Kausaler Schluss","legacyType":"Kausales Argument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Bei begrenzter Anpassungskapazität können zusätzliche Belastungen überproportional schwer bewältigbar werden.","assessment":"Ein kausaler Mechanismus begründet die nichtlineare Prognose. Die genaue Schadenskurve folgt daraus noch nicht.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus einer plausiblen Nichtlinearität darf keine punktgenaue unvermeidbare Schadenshöhe abgeleitet werden.","page":12}],"verification":"Nenne Modellannahmen, Schwellen und Unsicherheitsbereiche für konkrete Folgen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Heutige Folgen können den Ausgangspunkt für Zukunftsrisiken veranschaulichen.","reason":"Gletscher, Hitze und Landwirtschaft zeigen bereits Belastungen.","type":"Induktion (verallgemeinernd) · Prädiktiver Schluss","id":"A015","family":"Induktion (verallgemeinernd)","legacyType":"Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-07","page":2}],"implicitPremise":"Beobachtete heutige Folgen sind relevante, aber unvollständige Hinweise auf Risiken weiterer Erwärmung.","assessment":"Gegenwärtige Beispiele machen Zukunftsrisiken anschaulich; sie sind keine eigenständige vollständige Projektion.","fallacyChecks":[{"id":"VIII-13","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine proportionale Fortschreibung eines einzelnen Sommers wäre nicht durch das Beispiel gedeckt.","page":12}],"verification":"Verknüpfe Beispiele mit unabhängigen längerfristigen Modell- und Beobachtungsdaten.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Was unterscheidet eine Verdopplung der Erwärmung von einer Verdopplung der Schäden?","Welche Schlussregel verbindet Anpassungsgrenzen und nichtlineare Schäden?"],"teacher":"Die heutigen Folgen illustrieren die Richtung, ersetzen aber keine Modellierung der künftigen Risiken. Die Prognose ist an die im Gespräch angesprochene Politikentwicklung gebunden.","start":243.96,"id":"s05","end":300.84,"duration":56.88,"openingCueStart":243.96},{"title":"Warum sich die Schweiz stärker erwärmt","theme":"Wissen und Werte","arguments":[{"speaker":"Knutti","claim":"Das globale Mittel unterschätzt die im Gespräch erwartete Schweizer Erwärmung.","reason":"Die Schweiz erwärmte sich bisher stärker; Landflächen erwärmen sich stärker als Ozeane.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A016","family":"Kausaler Schluss","legacyType":"Kausales Argument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Ein bekannter Land-Meer-Mechanismus und regionale Beobachtungen können abweichende regionale Zukunftswerte stützen.","assessment":"Die Argumentation verbindet Erklärung und Projektion; das bisherige Verhältnis ist kein mathematisch festes Zukunftsgesetz.","fallacyChecks":[{"id":"VIII-13","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein historischer Faktor zwei darf nicht ungeprüft auf jede Jahreszeit und jedes Zukunftsszenario übertragen werden.","page":12}],"verification":"Trenne Messperiode, Jahreszeit, regionalen Mechanismus und projizierte Bandbreite.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Mehrere Ursachen tragen zur regionalen Entwicklung bei.","reason":"Neben Land-Meer-Unterschieden nennt er Luftreinhaltung und atmosphärische Zirkulation.","type":"Kausaler Schluss · Abduktion (Schluss auf die beste Erklärung)","id":"A017","family":"Kausaler Schluss","legacyType":"Mehrfaktorenerklärung","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-03","page":1}],"implicitPremise":"Wenn mehrere plausible Mechanismen die regionale Entwicklung beeinflussen, sollte ihre Kombination geprüft werden.","assessment":"Die Mehrfaktorenerklärung vermeidet eine vorschnelle einzige Ursache, liefert aber noch keine Gewichtung der Beiträge.","fallacyChecks":[{"id":"VIII-06","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Aussage widerspricht einer rein monokausalen Erklärung; die einzelnen Anteile bleiben offen.","page":11}],"verification":"Ergänze Evidenz für Grösse und Wechselwirkung der genannten Mechanismen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Aussage ist Beobachtung, welche Projektion, welche Erklärung?","Ist das bisherige Verhältnis von regionaler zu globaler Erwärmung automatisch für jede Zukunftsperiode gültig?"],"teacher":"Die Zahlen werden rekonstruiert, nicht als aktuelle Klimafakten bestätigt. Die Rückfrage der Moderatorin vereinfacht den Land-Meer-Zusammenhang; diese Vereinfachung sollte nicht ungeprüft als Definition übernommen werden.","start":300.84,"id":"s06","end":340.32,"duration":39.48,"openingCueStart":300.84},{"title":"Luftreinhaltung als Bumerang? Ursache und Bewertung","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch, als Einwand","claim":"Luftreinhaltung könnte als klimapolitisch kontraproduktiv erscheinen.","reason":"Ohne weniger Luftverschmutzung wäre ein Teil der beobachteten Erwärmung verdeckt geblieben.","type":"Kontrafaktisches Schliessen · Praktischer Schluss","id":"A018","family":"Kontrafaktisches Schliessen","legacyType":"Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-11","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenn Luftreinhaltung insgesamt mehr Schaden als Nutzen erzeugte, wäre ihre Rechtfertigung zu prüfen.","assessment":"Der kontrafaktische Einwand isoliert eine mögliche Nebenwirkung. Aus ihr allein folgt kein negatives Gesamturteil.","fallacyChecks":[{"id":"VI-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein nachteiliger Teilaspekt darf nicht ohne Gesamtabwägung zur Eigenschaft der ganzen Massnahme erklärt werden.","page":8}],"verification":"Rechne Gesundheitsvorteile und Klimawirkung getrennt aus und lege den Bewertungsmassstab offen.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Luftreinhaltung erzeugt nicht die gesamte zugrunde liegende Erwärmung.","reason":"Verschmutzung hat einen Teil der Erwärmung zuvor maskiert; Reinigung macht ihn sichtbar.","type":"Kausaler Schluss · Kontrafaktisches Schliessen","id":"A019","family":"Kausaler Schluss","legacyType":"Kausale Präzisierung","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-11","page":2}],"implicitPremise":"Ein zuvor maskierender Einfluss ist von der zugrunde liegenden Ursache zu unterscheiden.","assessment":"Die Reinigung entfernt einen gegenläufigen Effekt; damit ist sie nicht als alleinige Ursache der gesamten Erwärmung ausgewiesen.","fallacyChecks":[{"id":"VIII-06","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Erklärung korrigiert eine Verkürzung auf Luftreinhaltung als einzige Ursache.","page":11}],"verification":"Präzisiere Aerosolwirkung und Treibhauswirkung mit getrennten kontrafaktischen Vergleichswelten.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine Klimawirkung allein rechtfertigt keine Rückkehr zur Luftverschmutzung.","reason":"Saubere Luft hat eigenständige gesundheitliche Vorteile.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A020","family":"Praktischer Schluss","legacyType":"Abwägungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine Massnahme ist unter Einbezug aller relevanten Folgen zu bewerten, nicht nur einer unerwünschten Wirkung.","assessment":"Gesundheitliche Vorteile sind für die politische Abwägung relevant. Ein solches Folgenargument entscheidet nicht über die Wahrheit der Klimadaten.","fallacyChecks":[{"id":"V-18","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Der praktische Nutzen-Schaden-Vergleich ist kein Appell an Konsequenzen als Wahrheitsbeweis.","page":7}],"verification":"Formuliere ein Gesamturteil mit Gesundheit, Klima, Verteilung und verfügbaren Alternativen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Der beschriebene Luftreinigungseffekt ist von fortgesetzter Erwärmung zu unterscheiden.","reason":"Luftreinhaltung bezeichnet er als weitgehend abgeschlossen, die Landflächenerwärmung als fortdauernd.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A021","family":"Kausaler Schluss","legacyType":"Differenzierung","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Ein historisch begrenzter Maskierungseffekt muss nicht dieselbe zukünftige Dynamik haben wie fortgesetzte Erwärmung.","assessment":"Die Mechanismen werden zeitlich unterschieden; die starke Abschlussbehauptung zur Luftreinhaltung benötigt eine sachliche Prüfung.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine als vollständig abgeschlossen dargestellte Entwicklung könnte die verbleibende Unsicherheit verdecken.","page":12}],"verification":"Bestimme Region und Zeitraum, auf die sich der behauptete Abschluss bezieht.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Folgt aus einer unerwünschten Nebenwirkung, dass eine Massnahme insgesamt falsch ist?","Welche zusätzlichen Prämissen wären für ein Gesamturteil nötig?"],"teacher":"Ein kausaler Zusammenhang ist kein vollständiges Nutzen-Schaden-Urteil. Die pauschale Abschlussbehauptung zur Luftreinhaltung bleibt eine zu prüfende Gesprächsaussage.","start":340.32,"id":"s07","end":414.0,"duration":73.68,"openingCueStart":340.32},{"title":"Hitzesommer als konkretisiertes Risikobeispiel","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch","claim":"Die Rede vom Doppelten ist ohne Messgrösse unklar.","reason":"Gletschermasse, Wasserstand und Hitzetage sind verschiedene Grössen.","type":"Dialektischer Schluss","id":"A022","family":"Dialektischer Schluss","legacyType":"Begriffspräzisierung","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine Verdopplungsbehauptung ist nur prüfbar, wenn die betroffene Grösse und ihre Beziehung zur Temperatur feststehen.","assessment":"Bleisch fordert eindeutige Bezugsgrössen. Der Einwand betrifft die Schlussgrundlage, nicht das blosse Vorhandensein einer Zahl.","fallacyChecks":[{"id":"VI-05","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Nachfrage verhindert einen unbemerkten Wechsel zwischen Temperatur, Hitzetagen und Wasserständen.","page":8}],"verification":"Definiere für jede Folgenaussage eigenen Nenner, Zeitraum und Wirkungszusammenhang.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Der angesprochene Sommer veranschaulicht die Belastung einer wärmeren Zukunft.","reason":"Er nennt Todesfälle, Hitze, Wasserknappheit und Gletschermassenverlust; in einer Drei-Grad-Welt würden solche Sommer häufiger.","type":"Prädiktiver Schluss · Statistischer Schluss · Induktion (verallgemeinernd)","id":"A023","family":"Prädiktiver Schluss","legacyType":"Beispiel- und Prognoseargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-05","page":2},{"id":"I-02","page":1}],"implicitPremise":"Ein gegenwärtiger Belastungssommer kann illustrieren, wie eine veränderte Häufigkeitsverteilung den Alltag prägen würde.","assessment":"Die Zukunftshäufigkeit ist ein statistisch gestützter Prognoseanspruch; die aufgezählten Folgen sind seine Illustration, nicht sein Beweis.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der Einzel-Sommer wäre anekdotischer Beweis, falls er die Modell- und Häufigkeitsdaten ersetzen soll.","page":9}],"verification":"Belege die genannte Häufigkeit und trenne Klimaattribution von einzelnen Schadensmeldungen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Messgrösse fordert Bleisch ein?","Was beweist ein Einzelereignis, und wofür benötigt man eine statistische Zuordnung?"],"teacher":"Ein Sommer ist anschaulich, aber als Einzelbeispiel keine vollständige Attributionsstudie. Die Jahres- und Todesfallangaben im neuen Transkript und in den Untertiteln nicht als unabhängig verifiziert ausgeben.","start":414.0,"id":"s08","end":475.76,"duration":61.76,"openingCueStart":414.0},{"title":"Gletscherbilder: Anschaulichkeit und wissenschaftliche Erwartung","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch","claim":"Bilder und anschauliche Volumenvergleiche schaffen öffentliche Aufmerksamkeit.","reason":"Gletscherverschwinden und der Trinkwasservergleich machen abstrakte Mengen vorstellbar.","type":"Analogieschluss · Kausaler Schluss","id":"A024","family":"Analogieschluss","legacyType":"Veranschaulichung","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-06","page":2}],"implicitPremise":"Anschauliche Bilder und bekannte Grössen können abstrakte Mengen kommunizierbar machen.","assessment":"Der Trinkwasservergleich überträgt nur eine Mengenanschauung, nicht Nutzbarkeit oder zeitliche Verfügbarkeit.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Analogie wäre falsch, wenn geschmolzenes Gletschervolumen mit verfügbarer Trinkwasserversorgung gleichgesetzt würde.","page":12}],"verification":"Nenne die verglichenen Volumina und begrenze die Übertragung ausdrücklich auf die Grössenordnung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die Gletscherentwicklung überrascht ihn wissenschaftlich weniger als emotional.","reason":"Die beobachtete Richtung entspricht langjährigen Szenarien.","type":"Abduktion (Schluss auf die beste Erklärung) · Defeasibles (aufhebbares) Schliessen","id":"A025","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Konsistenzargument","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-09","page":2}],"implicitPremise":"Eine Beobachtung, die eine zuvor formulierte Modellprognose erwartet, kann das Modell stützen, ohne es eindeutig zu beweisen.","assessment":"Die Übereinstimmung ist abduktive Evidenz, keine deduktive Bestätigung nur einer möglichen Ursache.","fallacyChecks":[{"id":"IV-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus «Modell P erwartet Q» und «Q beobachtet» folgt nicht zwingend «P ist wahr».","page":5}],"verification":"Prüfe Vorhersagezeitpunkt, konkurrierende Modelle und unabhängige Daten.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche argumentative Funktion hat der Trinkwasservergleich?","Ist Übereinstimmung mit einer Vorhersage dasselbe wie deren vollständige Bestätigung?"],"teacher":"Der Vergleich illustriert eine Menge; er begründet keine Gleichheit von Nutzbarkeit oder Verteilung des Wassers. Die Modellbestätigung verlangt mehr als ein ausgewähltes Beispiel.","start":475.76,"id":"s09","end":541.76,"duration":66.0,"openingCueStart":475.76},{"title":"Heimatverlust und Folgen jenseits des Geldes","theme":"Wissen und Werte","arguments":[{"speaker":"Knutti","claim":"Landschaftsveränderung betrifft persönliche und kulturelle Identität.","reason":"Eigene Bergerfahrungen zeigen ihm eine nicht mehr vertraute Landschaft.","type":"Induktion (verallgemeinernd)","id":"A026","family":"Induktion (verallgemeinernd)","legacyType":"Erfahrungsargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1}],"implicitPremise":"Eigene wiederholte Erfahrungen können eine persönliche Landschaftsveränderung belegen, nicht ihre allgemeine Häufigkeit.","assessment":"Die Passage trägt als Erlebnis- und Bedeutungsbericht; für Verallgemeinerungen ist ihre Reichweite enger.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Erinnerung würde zum anekdotischen Beweis, wenn sie Messreihen oder Klimazuschreibung ersetzen müsste.","page":9}],"verification":"Trenne persönliche Heimatbindung, dokumentierte Veränderung und kausale Attribution.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Gletscherschwund betrifft auch kulturelle Verständlichkeit.","reason":"Ein Volkslied könnte seinen unmittelbar erlebbaren Bezug verlieren.","type":"Analogieschluss · Prädiktiver Schluss","id":"A027","family":"Analogieschluss","legacyType":"Kulturelle Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn ein kultureller Text auf erfahrbare Landschaft verweist, kann deren Verschwinden seine unmittelbare Verständlichkeit verändern.","assessment":"Ein konkretes Lied illustriert einen möglichen kulturellen Verlust; es beweist weder allgemeines Unverständnis noch dessen Ausmass.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Von einem Lied lässt sich nicht auf das Verschwinden aller kulturellen Verständlichkeit schliessen.","page":9}],"verification":"Formuliere den Verlust als eingeschränkte Möglichkeit und unterscheide Wissen von eigener Anschauung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Gletscherverlust berührt mehrere Lebens- und Wirtschaftsbereiche.","reason":"Er nennt Landwirtschaft, Rheinschifffahrt, Fischerei, Stromproduktion und Menschen in den Bergen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A028","family":"Kausaler Schluss","legacyType":"Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Der Wegfall eines für mehrere Systeme relevanten natürlichen Speichers kann mehrere Nutzungen und Lebenswelten verändern.","assessment":"Es werden verschiedene Wirkungswege behauptet, nicht nur ein monetärer Verlust.","fallacyChecks":[{"id":"VIII-09","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine blosse Folgenliste ersetzt keine Erklärung des jeweiligen Übertragungsmechanismus.","page":12}],"verification":"Erläutere Wasserhaushalt, Saisonalität und betroffene Nutzungen jeweils separat.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Was kann ein persönlicher Erfahrungsbericht belegen und was nicht?","Welche Wertannahme verbindet Heimatbindung mit einem Schutzanspruch?"],"teacher":"Erlebnis und Liedbezug erschliessen Wertdimensionen, liefern aber allein weder die Klimazuschreibung noch eine konkrete politische Priorität.","start":541.76,"id":"s10","end":625.52,"duration":83.76,"openingCueStart":541.76},{"title":"Unsichtbare Risiken: Hitze, Arbeit, Anpassungsgrenzen","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch","claim":"Öffentliche Aufmerksamkeit könnte falsch gewichtet sein.","reason":"Eine angesprochene Studie nennt Hitzetote, Produktivitätsverluste und Grenzen tiefer Skigebiete.","type":"Praktischer Schluss","id":"A029","family":"Praktischer Schluss","legacyType":"Priorisierungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Öffentliche Prioritäten sollen Schwere und Eintrittswahrscheinlichkeit von Schäden berücksichtigen, nicht nur Bildwirkung.","assessment":"Die Studie wird als relevanter Sachbezug für eine praktische Priorisierungsfrage angeführt; ihre Details sind nicht im Gespräch vollständig belegt.","fallacyChecks":[{"id":"V-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der Behördenname allein wäre kein Ersatz für Methodik und Nachprüfbarkeit der Studie.","page":6}],"verification":"Ermittle Originalstudie, Szenario, Vergleichszeitraum und Unsicherheiten.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Sichtbarkeit bestimmt nicht die Grösse eines Risikos.","reason":"Todesfälle in Pflegeheimen fallen weniger auf als Gletscherbilder.","type":"Dialektischer Schluss","id":"A030","family":"Dialektischer Schluss","legacyType":"Vergleichsargument","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Leicht sichtbare Ereignisse müssen nicht die grössten oder häufigsten Schäden sein.","assessment":"Die Gegenüberstellung von Bildern und Pflegeheimfolgen kritisiert einen Wahrnehmungsmassstab, nicht die Existenz sichtbarer Schäden.","fallacyChecks":[{"id":"X-07","status":"diskutiert","label":"Diskutiertes Muster – nicht individuell diagnostiziert","reason":"Verfügbarkeitsheuristik ist ein möglicher Wahrnehmungsmechanismus und keine bewiesene Eigenschaft jeder Zuschauerperson.","page":13}],"verification":"Vergleiche tatsächliche Schadensverteilung und mediale Aufmerksamkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Klimafolgen bleiben auch bei Anpassung kostenwirksam.","reason":"Hitze, Kühlung, Dürren und Wintersport betreffen mehrere Sektoren; Anpassung hat Grenzen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A031","family":"Kausaler Schluss","legacyType":"Kumulatives Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn Anpassung begrenzt ist und selbst Ressourcen benötigt, bleiben trotz Anpassung relevante Schäden oder Kosten.","assessment":"Der Schluss verknüpft mehrere sektorale Mechanismen mit einer bedingten Zukunftserwartung.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus Anpassungsgrenzen folgt keine für jedes Szenario feststehende Gesamtschadenssumme.","page":12}],"verification":"Trenne Restschäden, Anpassungskosten und unterschiedliche Anpassungsstrategien.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Bezifferte Schäden können die Gesamtkosten unterschätzen.","reason":"Biodiversität und internationale Folgen sind schwer zu monetarisieren.","type":"Dialektischer Schluss · Defeasibles (aufhebbares) Schliessen","id":"A032","family":"Dialektischer Schluss","legacyType":"Unsicherheitsargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-09","page":2}],"implicitPremise":"Nicht gemessene oder nicht monetarisierte Folgen sind nicht schon deshalb null.","assessment":"Die Aussage begrenzt den Erkenntnisanspruch einer Geldsumme. Sie beweist nicht, dass beliebige zusätzlich vermutete Schäden eintreten.","fallacyChecks":[{"id":"V-11","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Zurückweisung von «nicht beziffert, also nicht vorhanden» darf nicht in «nicht widerlegt, also sicher vorhanden» umschlagen.","page":7}],"verification":"Benenne konkrete Wirkungspfade und dokumentiere, welche Folgen in der Rechnung fehlen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Warum ist «sichtbar» kein ausreichendes Relevanzkriterium?","Ist fehlende Quantifizierung ein Beleg für einen Schaden von null?"],"teacher":"Die Zahlen aus dem Gespräch sind als Studienverweise zu behandeln. Welche Studie, welches Szenario, welcher Zeitraum und welche Schadensdefinition gelten, muss separat recherchiert werden.","start":625.52,"id":"s11","end":750.04,"duration":124.52,"openingCueStart":625.52},{"title":"Elektromobilität und Gesundheitsnutzen","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Elektromobilität kann neben Klimaschutz auch Gesundheitsnutzen haben.","reason":"Verkehr verursacht Luftbelastung und Gesundheitskosten; weniger lokale Schadstoffe können Asthmaerkrankungen reduzieren.","type":"Kausaler Schluss · Praktischer Schluss","id":"A033","family":"Kausaler Schluss","legacyType":"Zusatznutzenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Weniger verkehrsbedingte Schadstoffbelastung kann neben Klimawirkungen gesundheitlichen Nutzen erzeugen.","assessment":"Ein Zusatznutzen ist für eine Handlungsempfehlung relevant, aber vom gesamten Lebenszyklusvergleich zu trennen.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Gesundheit hängt nicht allein vom Antrieb ab; andere Verkehrseffekte dürfen nicht ausgeblendet werden.","page":11}],"verification":"Prüfe lokale Emissionen, Abrieb, Strommix und Verkehrsaufkommen getrennt.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Was ist hier Hauptziel und was Zusatznutzen?","Welche Systemgrenzen braucht ein Vergleich zwischen Antrieben?"],"teacher":"Die Aussage zu lokaler Luftqualität ist von Lebenszyklusemissionen, Reifenabrieb, Strommix und allgemeinem Verkehrsaufkommen zu unterscheiden.","start":750.04,"id":"s12","end":772.76,"duration":22.72,"openingCueStart":750.04},{"title":"«Wunderbares Beispiel»: Illustration oder Zynismus?","theme":"Kommunikation","arguments":[{"speaker":"Bleisch","claim":"Die Formulierung könnte gegenüber Leidenden unangemessen wirken.","reason":"Knutti bezeichnete einen schädlichen Sommer als wunderbares Beispiel.","type":"Dialektischer Schluss · Praktischer Schluss","id":"A034","family":"Dialektischer Schluss","legacyType":"Sprachkritik","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-08","page":2}],"implicitPremise":"Öffentliche Sprache soll Leiden nicht als moralisch erfreulich darstellen.","assessment":"Bleisch prüft die Angemessenheit einer mehrdeutigen Formulierung; das ist noch keine Widerlegung der Risikoaussage.","fallacyChecks":[{"id":"VI-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"«Wunderbar» als illustrativ nützlich darf nicht ohne Begründung in moralisch gut umgedeutet werden.","page":8}],"verification":"Frage zuerst nach der gemeinten Bewertungsdimension.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Er bewertet den Erkenntnis- und Kommunikationswert, nicht das Leid positiv.","reason":"Ein konkretes Ereignis macht lokale und gegenwärtige Folgen leichter verständlich.","type":"Dialektischer Schluss","id":"A035","family":"Dialektischer Schluss","legacyType":"Begriffliche Unterscheidung","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Ein Ereignis kann als Warnbeispiel aufschlussreich und zugleich moralisch schlecht sein.","assessment":"Die Klarstellung löst eine Mehrdeutigkeit auf. Ein Widerspruch folgt nur, wenn beide Bewertungen dieselbe Hinsicht betreffen.","fallacyChecks":[{"id":"VI-05","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Passage unterscheidet kommunikativen Erkenntniswert von positiver Bewertung des Leids.","page":8}],"verification":"Ersetze das mehrdeutige Adjektiv durch «anschaulich» und benenne die Schäden weiter klar.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche beiden Bedeutungen von «wunderbar» geraten aneinander?","Widerlegt die Sprachkritik den Inhalt der Klimaaussage?"],"teacher":"Die Trennung von kommunikativer Nützlichkeit und moralischer Bewertung löst eine mögliche Mehrdeutigkeit auf. Sie immunisiert die Wortwahl nicht gegen Kritik.","start":772.76,"id":"s13","end":824.64,"duration":51.88,"openingCueStart":772.76},{"title":"Zahlen, Gefahrenurteil und Wissenschaftskommunikation","theme":"Wissen und Werte","arguments":[{"speaker":"Knutti","claim":"Wissenschaftliche Zahlen benötigen Interpretation und Kontext.","reason":"Die Zahl 2,8 beantwortet weder die Bedeutungs- noch die Handlungsfrage von selbst.","type":"Praktischer Schluss","id":"A036","family":"Praktischer Schluss","legacyType":"Erkenntnistheoretisches Argument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Information soll die für Urteile relevanten Folgen und Voraussetzungen verständlich machen.","assessment":"Der Übersetzungsauftrag ist ein praktischer Schluss über die Funktion von Wissenschaftskommunikation.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus der Existenz einer Zahl allein folgt ohne Kommunikations- und Verantwortungsnorm keine persönliche Pflicht des Forschers.","page":12}],"verification":"Ergänze den normativen Auftrag und die Grenzen fachlicher Zuständigkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die Bewertung als gefährlich enthält ein Werturteil.","reason":"Gefahr setzt einen Bezug auf schützenswerte Güter und akzeptable Risiken voraus.","type":"Dialektischer Schluss","id":"A037","family":"Dialektischer Schluss","legacyType":"Begriffliches Argument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Die Zuschreibung «gefährlich» verbindet empirische Schadensmöglichkeiten mit einer Wertung schützenswerter Güter.","assessment":"Dies ist eine begriffliche Analyse, kein bloss statistischer oder rein deduktiver Beweis politischer Pflichten.","fallacyChecks":[{"id":"IX-01","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Passage macht die normative Zusatzprämisse gerade sichtbar, statt sie aus einer Messzahl abzuleiten.","page":12}],"verification":"Benenne Güter, akzeptable Risiken und die Gruppe, deren Risiko bewertet wird.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Wissenschaft kann demokratische Entscheidungen informieren, aber nicht ersetzen.","reason":"Ihre Übersetzungsarbeit macht Folgen und Optionen verständlich; die politische Entscheidung bleibt offen.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A038","family":"Praktischer Schluss","legacyType":"Rollenargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Demokratische Entscheidungskompetenz soll erhalten bleiben, während Fachwissen die Optionen informiert.","assessment":"Der Schluss grenzt legitime Information von der alleinigen Entscheidungsmacht wissenschaftlicher Experten ab.","fallacyChecks":[{"id":"V-07","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Fachkompetenz wird nicht als hinreichende Autorität für jede politische Entscheidung beansprucht.","page":6}],"verification":"Lege offen, welche Aussagen fachlich und welche wertend oder politisch sind.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Wo verläuft die Grenze zwischen Sachinformation und Wertung?","Formuliere eine normative Zusatzprämisse, die aus einer Risikobeschreibung eine Handlungsforderung macht."],"teacher":"Die Wanderprediger-Metapher ist eine Selbstbeschreibung, keine zusätzliche empirische Begründung. Risiken enthalten sowohl empirische als auch evaluative Elemente.","start":824.64,"id":"s14","end":935.76,"duration":111.12,"openingCueStart":824.64},{"title":"Politisches Engagement und selbst gesetzte Ziele","theme":"Wissen und Werte","arguments":[{"speaker":"Bleisch, als Einwand","claim":"Politisches Kampagnenengagement könnte wissenschaftliche Rollengrenzen überschreiten.","reason":"Sie nennt Knuttis Beteiligung an politischen Komitees.","type":"Dialektischer Schluss","id":"A039","family":"Dialektischer Schluss","legacyType":"Rollen- und Glaubwürdigkeitskritik","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Politische Rollen können die Wahrnehmung wissenschaftlicher Neutralität beeinflussen und verdienen deshalb Prüfung.","assessment":"Rollen- und Transparenzfragen sind legitim. Sie erledigen die fachlichen Argumente aber nicht automatisch.","fallacyChecks":[{"id":"V-03","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus Kampagnenbeteiligung allein auf sachliche Falschheit zu schliessen wäre circumstantial ad hominem.","page":6}],"verification":"Prüfe mögliche Interessenkonflikte und den Wahrheitsanspruch der konkreten Aussage getrennt.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Öffentliche Begriffe dürfen an ihrer sachlichen Bedeutung gemessen werden.","reason":"Er bestreitet, dass die angesprochene Nachhaltigkeitsinitiative dem behaupteten Nachhaltigkeitszweck entspreche.","type":"Dialektischer Schluss","id":"A040","family":"Dialektischer Schluss","legacyType":"Begriffskritik","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Ein politisches Etikett soll nicht als Beleg dafür gelten, dass der bezeichnete Vorschlag das behauptete Ziel erreicht.","assessment":"Die Begriffsabgrenzung ist nachvollziehbar, bleibt zur konkreten Initiative aber weitgehend eine Behauptung.","fallacyChecks":[{"id":"VI-12","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine eigene wertende Definition von Nachhaltigkeit darf die strittige Sache nicht bloss sprachlich vorentscheiden.","page":9}],"verification":"Vergleiche festgelegte Nachhaltigkeitskriterien mit dem tatsächlichen Inhalt der Initiative.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine Ziel-Mittel-Lücke kann wissenschaftlich untersucht werden.","reason":"Die Schweiz hat Klimaziele anerkannt; ihr tatsächlicher Kurs ist daran messbar.","type":"Deduktion · Dialektischer Schluss","id":"A041","family":"Deduktion","legacyType":"Konsistenzargument","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-14","page":2}],"implicitPremise":"Wenn messbare Ziele festgelegt sind, kann der tatsächliche Entwicklungspfad auf Übereinstimmung mit ihnen geprüft werden.","assessment":"Der allgemeine Prüfauftrag ist bedingt deduktiv rekonstruierbar; ob der Pfad tatsächlich nicht genügt, ist eine zusätzliche empirische Frage.","fallacyChecks":[{"id":"V-07","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Eine wissenschaftlich prüfbare Ziel-Mittel-Diagnose ist weder allein wegen ihrer politischen Relevanz wahr noch falsch.","page":6}],"verification":"Trenne Zielvorgabe, Modellierung des Ist-Kurses und normative Wahl neuer Instrumente.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Zur Zielerreichung braucht es politische Regeln, ohne dass Wissenschaft deren genaue Form diktieren muss.","reason":"Ohne CO2-Regelung sieht er die Ziele als nicht erreichbar an.","type":"Praktischer Schluss","id":"A042","family":"Praktischer Schluss","legacyType":"Zweck-Mittel-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wer ein anerkanntes Ziel erreichen will, soll dafür notwendige und vertretbare Mittel bereitstellen.","assessment":"Der Schluss ist praktisch. Notwendigkeit irgendeines Rahmens begründet noch nicht die Hinlänglichkeit oder Alternativlosigkeit eines bestimmten Gesetzes.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Notwendigkeit von Regeln darf nicht mit ausreichender Wirkung jeder Regel verwechselt werden.","page":6}],"verification":"Vergleiche Instrumente, Nebenwirkungen und Zielerreichung unter offen gelegten Annahmen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Prämisse ist empirisch, welche schon politisch normativ?","Folgt aus «Ziel verfehlt» zwingend ein bestimmtes Gesetz?"],"teacher":"Die fachliche Diagnose ist von der Auswahl einer konkreten Regelung zu trennen. Die Aussage zur Initiative wird im Gespräch eher behauptet als hier ausführlich begründet.","start":935.76,"id":"s15","end":1047.44,"duration":111.68,"openingCueStart":935.76},{"title":"Transformation als Chance – und eine zugespitzte Alternative","theme":"Kommunikation","arguments":[{"speaker":"Knutti","claim":"Fakten müssen übersetzt werden, damit sie handlungsrelevant werden.","reason":"Zahlen allein erklären ihre Folgen und Optionen nicht.","type":"Praktischer Schluss","id":"A043","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Fakten sollen für betroffene Menschen in ihren Folgen und Handlungsmöglichkeiten verstehbar sein.","assessment":"Die erneute Übersetzungsforderung folgt einem Kommunikationsziel; Wiederholung allein liefert dafür keinen zusätzlichen Sachbeleg.","fallacyChecks":[{"id":"VI-18","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Wiederaufnahme einer begründeten Forderung ist nicht schon ein Argument durch Wiederholung.","page":9}],"verification":"Verweise auf die zuvor genannten Informationslücken und ergänze konkrete Interpretationshilfen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Aktive Zukunftsgestaltung kann gesellschaftlichen Nutzen erzeugen.","reason":"Infrastruktur und Innovation können einen ohnehin laufenden Umbruch positiv prägen.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A044","family":"Praktischer Schluss","legacyType":"Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn gesellschaftliche Veränderung unvermeidbar ist, soll man vertretbare Möglichkeiten zur Verbesserung nutzen.","assessment":"Der Nutzen wird als Zukunftsmöglichkeit, nicht als notwendiger Erfolg jedes Infrastrukturvorhabens rekonstruiert.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Gestaltungsabsicht allein garantiert keine bessere Schweiz.","page":12}],"verification":"Nenne konkrete Projekte, Erfolgskriterien, Verteilungsfolgen und Alternativen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine rein rückwärtsgewandte Haltung ist keine tragfähige Zukunftsstrategie.","reason":"Die Welt verändert sich unabhängig vom Wunsch nach früheren Zuständen.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A045","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine Strategie muss auf veränderte Zukunftsbedingungen reagieren können, statt nur frühere Zustände vorauszusetzen.","assessment":"Die Kritik an reinem Rückwärtsblick hat einen praktischen Kern; die Gegenüberstellung mit einer Rückkehr nach 1800 verkürzt jedoch das Spektrum.","fallacyChecks":[{"id":"VI-03","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der Fehler liegt vor, wenn nur die eigene Transformation und unmögliche Rückkehr als reale Optionen gelten.","page":8},{"id":"V-06","status":"rhetorik","label":"Rhetorischer Effekt – kein alleiniger logischer Nachweis","reason":"Die MAGA-Assoziation kann Abwertung verstärken, ersetzt aber keine Widerlegung anderer Transformationsvorschläge.","page":6}],"verification":"Diskutiere auch konservative, schrittweise und abweichende Zukunftsstrategien auf ihre Folgen hin.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Verengt der Gegensatz zwischen Zukunftsgestaltung und Rückkehr nach 1800 die Optionen unzulässig?","Welche Position zwischen den beiden Polen bleibt denkbar?"],"teacher":"Die zugespitzte Gegenüberstellung kann ein falsches Dilemma nahelegen, sofern sie als vollständige Menge der Möglichkeiten verstanden wird. Als rhetorischer Kontrast ist sie noch keine logische Widerlegung anderer Strategien.","start":1047.44,"id":"s16","end":1128.68,"duration":81.24,"openingCueStart":1047.44},{"title":"Moralischer Vorwurf, Abwehr und positive Selbstwirksamkeit","theme":"Kommunikation","arguments":[{"speaker":"Bleisch","claim":"Der Anspruch, kein Prediger zu sein, steht erklärungsbedürftig neben dem politischen Appell.","reason":"Sie kontrastiert die Selbstbeschreibung mit dem Veränderungsdruck.","type":"Dialektischer Schluss","id":"A046","family":"Dialektischer Schluss","legacyType":"Konsistenzkritik","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Selbstbeschreibung und tatsächlich beanspruchte Rolle sollen konsistent sein.","assessment":"Die Prüfung einer Spannung ist legitim. «Prediger» als Metapher und als bevormundende Moralinstanz müssen dabei unterschieden werden.","fallacyChecks":[{"id":"VI-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Widerspruch wird nur scheinbar erzeugt, wenn «Prediger» zwischen zwei Bedeutungen wechselt.","page":8}],"verification":"Definiere, welche politische Einflussnahme Knutti tatsächlich ablehnt.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Persönliche moralische Beschämung kann Veränderung blockieren.","reason":"Betroffene reagieren mit Leugnung, Verharmlosung, Vergleich und Ohnmacht.","type":"Kausaler Schluss · Defeasibles (aufhebbares) Schliessen","id":"A047","family":"Kausaler Schluss","legacyType":"Kausales Argument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-09","page":2}],"implicitPremise":"Identitätsbedrohende Beschämung kann Abwehr auslösen und damit Verhaltensänderung erschweren.","assessment":"Das ist eine plausible aufhebbare Wirkungsannahme, keine Aussage über die Geltung der Norm und keine Garantie derselben Reaktion bei allen.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Von beobachteter Abwehr auf generelle Wirkungslosigkeit jeder Moral zu schliessen wäre zu weit.","page":9}],"verification":"Unterscheide persönliche Beschämung, sachliche Normbegründung und empirische Wirkung in verschiedenen Zielgruppen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Positive Beteiligung kann Handlungsbereitschaft fördern.","reason":"Gestaltungsmöglichkeiten, Freude und soziale Unterstützung stärken Selbstwirksamkeit.","type":"Kausaler Schluss · Praktischer Schluss","id":"A048","family":"Kausaler Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Eine Strategie, die Selbstwirksamkeit und Unterstützung fördert, kann Beteiligung erhöhen.","assessment":"Die praktische Empfehlung hängt an einem empirischen Mechanismus und dem Ziel wirksamer Beteiligung.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Positive Gefühle sind nicht die einzige Bedingung politischer Handlungsfähigkeit.","page":11}],"verification":"Prüfe Zugang, materielle Hindernisse und Vergleichsdaten statt ausschliesslich Kommunikationswirkung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Rekonstruiere Abwehrreaktion und Alternativstrategie.","Begründet geringe Wirksamkeit eines Vorwurfs, dass die zugrunde liegende Norm falsch ist?"],"teacher":"Wirkung und Geltung sind verschiedene Fragen. Knuttis Verallgemeinerung über die Wirkung von Moral braucht empirische Einschränkungen; die Beispiele belegen nicht jede moralische Kommunikation.","start":1128.68,"id":"s17","end":1219.76,"duration":91.08,"openingCueStart":1128.68},{"title":"Sklaverei und Frauenstimmrecht: Gegenbeispiele zur Moralkritik","theme":"Gerechtigkeit","arguments":[{"speaker":"Bleisch","claim":"Moralische Argumentation kann gesellschaftliche Veränderungen tragen.","reason":"Abschaffung der Sklaverei und Frauenstimmrecht sind historische Gegenbeispiele zur pauschalen Wirkungslosigkeit.","type":"Deduktion · Dialektischer Schluss","id":"A049","family":"Deduktion","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-14","page":2}],"implicitPremise":"Ein belegter Fall wirksamer moralischer Mobilisierung widerlegt die Allaussage, Moral wirke niemals.","assessment":"Als Gegenbeispiel ist der Schluss gegen eine pauschale Negation logisch stark. Er zeigt nur Möglichkeit und nicht allgemeinen oder alleinigen Erfolg.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die historischen Veränderungen dürften nicht ausschliesslich moralischen Argumenten zugeschrieben werden.","page":11}],"verification":"Formuliere die angegriffene Allaussage genau und belege den tatsächlichen Beitrag moralischer Mobilisierung.","formalRule":{"id":"III-02","page":4,"scope":"Begrenzte Existenzfolgerung aus belegtem Fall","explanation":"Wenn mindestens eine historische Bewegung einen wirksamen moralischen Beitrag enthielt, gibt es wirksame moralische Mobilisierung. Das widerspricht «keine moralische Mobilisierung wirkt», zeigt aber keine universelle Erfolgsregel."},"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Klimapolitik könnte von moralischer Mobilisierung profitieren.","reason":"Menschenwürde und Gleichberechtigung mobilisierten frühere Bewegungen.","type":"Analogieschluss · Prädiktiver Schluss","id":"A050","family":"Analogieschluss","legacyType":"Historische Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-07","page":2}],"implicitPremise":"Eine Mobilisierungsform, die in vergleichbaren Konflikten beitrug, könnte unter ähnlichen Bedingungen auch hier beitragen.","assessment":"Die Übertragung von Sklaverei und Frauenstimmrecht auf Klimaschutz ist ein Analogieschluss, kein Erfolgsnachweis.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Unterschiede in Betroffenheit, Institutionen und Konfliktstruktur können die Analogie begrenzen.","page":12}],"verification":"Benenne gemeinsame Mechanismen und relevante Unterschiede der Bewegungen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welchen Umfang von Knuttis Aussage kann ein Gegenbeispiel widerlegen?","Welche Unterschiede zwischen damaligen Kämpfen und Klimaschutz begrenzen die Analogie?"],"teacher":"Die Beispiele stützen die Möglichkeit moralischer Mobilisierung, garantieren aber nicht deren Erfolg unter jeder Bedingung. Der argumentative Streit bleibt im Gespräch teilweise offen.","start":1219.76,"id":"s18","end":1252.44,"duration":32.68,"openingCueStart":1219.76},{"title":"Handlungsfähigkeit der Schweiz","theme":"Gerechtigkeit","arguments":[{"speaker":"Knutti","claim":"Die Schweiz ist besonders handlungsfähig.","reason":"Er nennt Innovation, Wohlstand, Bildung, Forschung und politische Stabilität.","type":"Induktion (verallgemeinernd) · Defeasibles (aufhebbares) Schliessen","id":"A051","family":"Induktion (verallgemeinernd)","legacyType":"Kumulatives Fähigkeitsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-09","page":2}],"implicitPremise":"Mehrere relevante Ressourcen sprechen vorläufig für hohe Handlungskapazität.","assessment":"Die Ressourcenaufzählung stützt eine graduelle Fähigkeitsbehauptung; die Superlative des Gesprächs benötigen einen Vergleichsmassstab.","fallacyChecks":[{"id":"VI-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Gute Einzelindikatoren garantieren nicht, dass das Gesamtsystem jede konkrete Transformation bewältigen kann.","page":8}],"verification":"Definiere das Handlungsziel und prüfe technische, finanzielle und institutionelle Engpässe.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine Weigerung eines besonders fähigen Landes schwächt die Erwartung, andere könnten handeln.","reason":"Wenn selbst ein gut ausgestattetes Land nicht handelt, wird eine positive Vorreitererwartung fragwürdig.","type":"Kontrafaktisches Schliessen · Praktischer Schluss","id":"A052","family":"Kontrafaktisches Schliessen","legacyType":"A-fortiori-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-11","page":2},{"id":"I-08","page":2}],"implicitPremise":"Besonders günstige Voraussetzungen begründen eine erhöhte Erwartung an einen Beitrag.","assessment":"Die rhetorische Frage verknüpft Fähigkeit mit Verantwortung. Sie beweist nicht, dass andere Länder weniger gut handeln könnten.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus hoher Leistungsfähigkeit allein folgt ohne Verantwortungsnorm noch keine Vorreiterpflicht.","page":12}],"verification":"Ergänze eine fair begründete Beitragsnorm und unterscheide Können von bereits bestehendem Handeln.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Führt Können allein zu Sollen? Ergänze die fehlende Norm.","Welche Angaben müssten die behauptete Sonderstellung belegen?"],"teacher":"Die rhetorische Frage «wer dann?» enthält eine Brücke vom Können zur Verantwortung. Sie ist ohne normative Zusatzprämisse kein rein empirischer Schluss.","start":1252.44,"id":"s19","end":1287.24,"duration":34.8,"openingCueStart":1252.44},{"title":"Kleiner Emissionsanteil – kleiner Hebel?","theme":"Gerechtigkeit","arguments":[{"speaker":"Bleisch, als Einwand","claim":"Schweizer Klimaschutz könnte global wenig bewirken.","reason":"Sie vergleicht geringe territoriale Anteile mit den hohen Anteilen der USA und Chinas.","type":"Statistischer Schluss · Praktischer Schluss","id":"A053","family":"Statistischer Schluss","legacyType":"Grössenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-05","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenn ein Akteur nur einen kleinen wirksamen Teil des Problems beeinflussen kann, muss sein Beitrag unter Wirkung und Kosten beurteilt werden.","assessment":"Ein Mengenvergleich kann eine Wirksamkeitsfrage eröffnen. Er zeigt nicht von selbst moralische Bedeutungslosigkeit oder fehlende Hebel.","fallacyChecks":[{"id":"IX-04","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der kleine Beitrag wäre zu Unrecht irrelevant, wenn nur die Existenz grösserer Emittenten als Grund genügte.","page":13}],"verification":"Lege Bilanzgrenzen und mögliche indirekte Wirkungen fest; trenne kleine Wirkung von Wirkung null.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Der territoriale Anteil bildet den schweizerischen Konsumfussabdruck unvollständig ab.","reason":"Importierte Kleidung, Geräte und Güter verursachen Emissionen im Ausland.","type":"Deduktion · Dialektischer Schluss","id":"A054","family":"Deduktion","legacyType":"Systemgrenzenargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-14","page":2}],"implicitPremise":"Eine Konsumbilanz muss die Emissionen der konsumierten importierten Güter einschliessen.","assessment":"Die Ergänzung der Bilanzgrenze ist konzeptionell nachvollziehbar; die genannte Verdreifachung ist eine gesonderte Datenbehauptung.","fallacyChecks":[{"id":"VI-05","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Territorial- und Konsumemissionen sind verschiedene Bedeutungen von «Schweizer Emissionen» und dürfen nicht unbemerkt vertauscht werden.","page":8}],"verification":"Kennzeichne die Bilanzart und belege den Umrechnungsfaktor mit passendem Jahr.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Einfluss ist nicht identisch mit territorialen Emissionen.","reason":"Handel, Banken, Versicherungen und Kapitalverflechtung ermöglichen zusätzliche Hebel.","type":"Kausaler Schluss · Defeasibles (aufhebbares) Schliessen","id":"A055","family":"Kausaler Schluss","legacyType":"Hebelargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-09","page":2}],"implicitPremise":"Wirtschaftliche Verflechtung kann Entscheidungen ausserhalb des eigenen Territoriums beeinflussen.","assessment":"Der Wirkungshebel ist eine kausale Möglichkeit, nicht identisch mit zugerechneten Emissionen oder automatisch ausgeübter Kontrolle.","fallacyChecks":[{"id":"VI-11","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Wirtschaftsschweiz darf nicht wie ein einheitlicher Akteur mit beliebiger Steuerungsmacht behandelt werden.","page":9}],"verification":"Nenne konkrete Akteure, Einflussinstrumente und kausale Wirkung statt eines undefinierten Weltrangs.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Bezugsgrösse wechselt zwischen beiden Positionen?","Widerlegt ein grösserer Konsumfussabdruck bereits die Frage nach der Wirksamkeit einzelner Massnahmen?"],"teacher":"Territorialbilanz, Konsumbilanz und Finanzhebel sind verschiedene Grössen. Knuttis Rangangabe zur Wirtschaftsschweiz bleibt ohne klare Definition nicht sauber überprüfbar.","start":1287.24,"id":"s20","end":1374.76,"duration":87.52,"openingCueStart":1287.24},{"title":"Wohlstandsverlust oder wirtschaftlicher Eigenvorteil?","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch","claim":"Umweltfreundlicheres Investieren kann Individuen finanziell belasten.","reason":"Sinkende Gewinne könnten Banken, Versicherungen oder Pensionskassen und ihre Begünstigten treffen.","type":"Prädiktiver Schluss · Praktischer Schluss","id":"A056","family":"Prädiktiver Schluss","legacyType":"Verteilungs- und Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Eine Handlung ist auch danach zu beurteilen, wie ihre Kosten zwischen Betroffenen verteilt werden.","assessment":"Die mögliche Belastung einzelner Begünstigter ist ein relevanter Einwand, auch wenn gesellschaftlich ein Vorteil erwartet wird.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Umweltfreundlicheres Investieren führt nicht notwendig in jedem Portfolio zu geringeren Renditen.","page":12}],"verification":"Formuliere die Renditeannahme bedingt und untersuche Betroffene, Zeiträume und Risikoveränderung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die Verzichtsrechnung ist unvollständig, wenn Klimaschäden fehlen.","reason":"Externe Schäden werden in der privaten Gewinnrechnung nicht berücksichtigt.","type":"Dialektischer Schluss · Praktischer Schluss","id":"A057","family":"Dialektischer Schluss","legacyType":"Kostenbilanzargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-08","page":2}],"implicitPremise":"Ein Gesamtkostenurteil soll externe Schäden ebenso berücksichtigen wie private Erträge.","assessment":"Die Kostenkritik korrigiert eine unvollständige Rechnung, beantwortet aber nicht automatisch die Frage der individuellen Belastung.","fallacyChecks":[{"id":"V-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine gesellschaftliche Vorteilsrechnung kann die strittige Frage nach konkreten Verlierern verfehlen.","page":8}],"verification":"Verbinde Gesamtrechnung mit Verteilungs- und Ausgleichsfragen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Alternativen können aus Eigeninteresse attraktiv werden.","reason":"Er nennt günstigere und bessere Wärmepumpen, Elektromobilität und erneuerbare Energien.","type":"Induktion (verallgemeinernd) · Prädiktiver Schluss · Praktischer Schluss","id":"A058","family":"Induktion (verallgemeinernd)","legacyType":"Nutzenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenn eine Alternative bei relevanten Gesamtkriterien besser abschneidet, kann sich ihr Einsatz auch privat lohnen.","assessment":"Die Behauptung gilt aufhebbar unter konkreten Vergleichsbedingungen. Technische Kosten, Preise und Verteilung sind nicht dasselbe.","fallacyChecks":[{"id":"VI-09","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Vorteil des Gesamtsystems darf nicht jeder Person oder jeder Anschaffung zugeschrieben werden.","page":8}],"verification":"Vergleiche konkrete Anwendungsfälle, Investitionskosten, Nutzungsdauer und Zugangsbedingungen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Wer trägt welche Kosten und wer erhält welchen Nutzen?","Ist ein volkswirtschaftlicher Vorteil automatisch ein Vorteil für jede einzelne Person?"],"teacher":"Knutti beantwortet die individuelle Verteilungsfrage teilweise mit einer Gesamtkostenperspektive. Kurzfristige Belastung und langfristiger Gesamtnutzen dürfen nicht gleichgesetzt werden.","start":1374.76,"id":"s21","end":1441.28,"duration":66.52,"openingCueStart":1374.76},{"title":"Innovation, Energieabhängigkeit und Kosten des Nichthandelns","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Investition in neue Technik kann Wettbewerbsmacht schaffen.","reason":"China dient ihm als Beispiel für wirtschaftliche und geopolitische Vorteile durch Innovation.","type":"Induktion (verallgemeinernd) · Kausaler Schluss","id":"A059","family":"Induktion (verallgemeinernd)","legacyType":"Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-06","page":2}],"implicitPremise":"Beobachtbare Technologieführerschaft kann durch frühere Forschung und Investition mitverursacht sein.","assessment":"China illustriert eine Ursache-Wirkungs-Hypothese; ein Fall isoliert deren Beitrag nicht von Marktgrösse und Industriepolitik.","fallacyChecks":[{"id":"VIII-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Andere gemeinsame Ursachen von Investitionen und Erfolg könnten übersehen werden.","page":11}],"verification":"Ergänze Vergleichsfälle und zeitliche Evidenz zur Wirkung der Investitionen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Fossile Abhängigkeit verursacht laufende Kosten und politische Risiken.","reason":"Er nennt Energieimporte und zusätzliche Kosten durch geopolitisch erhöhte Preise.","type":"Kausaler Schluss · Kontrafaktisches Schliessen","id":"A060","family":"Kausaler Schluss","legacyType":"Folgenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-11","page":2}],"implicitPremise":"Abhängigkeit von importierter Energie überträgt Preis- und Lieferstörungen auf die eigenen Kosten.","assessment":"Die geopolitische Kostenanfälligkeit ist kausal nachvollziehbar, aber die Höhe und vermeidbare Nettobelastung sind zusätzliche Fragen.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aktuelle Energiepreise dürfen nicht allein einer geopolitischen Ursache zugeschrieben werden.","page":11}],"verification":"Trenne Importausgaben, Preisaufschlag, inländische Alternativkosten und die relevante Gegenwelt.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Untätigkeit ist in einer vollständigen Kostenrechnung teuer.","reason":"Importausgaben, bezifferte Klimarisiken und schwer bezifferbare Schäden summieren sich.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A061","family":"Praktischer Schluss","legacyType":"Kumulatives Kostenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Eine rationale Handlungsabwägung muss erwartete relevante Kosten der Untätigkeit berücksichtigen.","assessment":"Die kumulative Rechnung kann Unterlassungskosten sichtbar machen; Aufzählung belegt weder Addierbarkeit noch die starke Rangbehauptung des Teuersten.","fallacyChecks":[{"id":"VII-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Unterschiedliche Horizonte und unsichere Schätzungen könnten in einer scheinbar eindeutigen Summe verschwinden.","page":11}],"verification":"Prüfe Doppelzählung, Systemgrenzen, Zeithorizonte und Diskontierung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Der Ausstieg kann langfristig wirtschaftlich vorteilhaft sein.","reason":"Erwartete vermiedene Kosten sollen die Veränderungskosten überwiegen.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A062","family":"Praktischer Schluss","legacyType":"Abwägungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn vermiedene Schäden und Abhängigkeiten die Übergangskosten überwiegen, ist der Wechsel langfristig wirtschaftlich vorteilhaft.","assessment":"Dies ist ein bedingter praktischer Kosten-Nutzen-Schluss, kein allein durch die Problembeschreibung gesicherter Erfolg.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Bedingung eines positiven Nettovorteils muss belegt werden, bevor der Vorteil als sicher gilt.","page":12}],"verification":"Vergleiche konkrete Ausstiegspfade und nenne Bandbreiten der Nettoeffekte.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Kostenpositionen dürfen addiert werden und wo droht Doppelzählung?","Welche Zeithorizonte und Gegenrechnungen braucht die starke Aussage über das Teuerste?"],"teacher":"Die Schlussformel ist eine zugespitzte Gesamtbehauptung. Für eine belastbare Kosten-Nutzen-Analyse fehlen in der Passage konkrete Szenarien, Diskontsätze und Alternativenvergleiche.","start":1441.28,"id":"s22","end":1526.04,"duration":84.76,"openingCueStart":1441.28},{"title":"Pro Kopf und Steueranalogie: Verantwortung trotz Kleinheit","theme":"Gerechtigkeit","arguments":[{"speaker":"Bleisch","claim":"Emissionen sollten für Gerechtigkeitsvergleiche auch pro Kopf betrachtet werden.","reason":"Länder haben stark unterschiedliche Bevölkerungsgrössen.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A063","family":"Praktischer Schluss","legacyType":"Bezugsgrössenargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Für ein an Personen orientiertes Gerechtigkeitsurteil ist neben der Gesamtmenge auch der Beitrag je Person relevant.","assessment":"Der gewählte Nenner wird begründet. Pro-Kopf-Betrachtung ersetzt aber nicht jede andere Verteilungsregel.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine bestimmte gerechte Lastenverteilung folgt nicht allein daraus, dass sich Pro-Kopf-Werte berechnen lassen.","page":12}],"verification":"Lege offen, warum gleiche Personenansprüche, Verursachung oder Leistungsfähigkeit gewichtet werden.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Die geringe Landesgrösse entlastet die Schweiz nicht automatisch.","reason":"Sie beschreibt hohe Pro-Kopf-Emissionen trotz kleiner Gesamtsumme.","type":"Praktischer Schluss","id":"A064","family":"Praktischer Schluss","legacyType":"Normatives Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Ein kleiner Staat kann eine Verpflichtung behalten, wenn seine Bewohner hohe relevante Beiträge verursachen.","assessment":"Die normative Entlastung wird bestritten, nicht eine beliebige physische Wirkung garantiert.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Hohe Pro-Kopf-Emissionen benötigen eine zusätzliche Verantwortungsnorm, um eine Pflicht zu begründen.","page":12}],"verification":"Verbinde Bilanzdaten mit einer expliziten und konsistent angewandten Beitragsregel.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Auch kleine Beiträge können verpflichtend sein.","reason":"Ein einzelner Steuerbeitrag ist im Gesamthaushalt klein und muss dennoch geleistet werden.","type":"Analogieschluss · Praktischer Schluss","id":"A065","family":"Analogieschluss","legacyType":"Steueranalogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Bei einem gemeinsamen Beitragssystem kann die geringe Einzelmenge eine allgemeine Beitragspflicht nicht aufheben.","assessment":"Die Steueranalogie stützt eine Beitragsnorm. Sie beweist weder gleiche Institutionen noch die Wirksamkeit jeder Klimamassnahme.","fallacyChecks":[{"id":"IX-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine identische Pflicht darf nicht ohne Berücksichtigung fehlender globaler Steuerinstitutionen übertragen werden.","page":13}],"verification":"Begründe die relevante gemeinsame Struktur und benenne Unterschiede bei Durchsetzung und Gegenleistung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Beliebige Aufteilung in kleine Einheiten kann keine allgemeine Entlastung begründen.","reason":"Auch jeder einzelne Mensch in China ist nur eine Person.","type":"Indirekter Beweis / Reductio ad absurdum · Dialektischer Schluss","id":"A066","family":"Indirekter Beweis / Reductio ad absurdum","legacyType":"Verallgemeinerungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-12","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine Entlastungsregel darf nicht so verallgemeinert werden, dass sie jede gemeinsame Verantwortung auflöst.","assessment":"Die Zerlegung grosser Länder in Einzelpersonen prüft die Konsequenz des Kleinheitsarguments. Der Widerspruch entsteht nur mit einer zusätzlich anerkannten Beitragsnorm.","fallacyChecks":[{"id":"VI-08","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Aussage zeigt gerade das Problem einer unbedingten Übertragung von Kleinheit der Teile auf Bedeutungslosigkeit des Ganzen.","page":8}],"verification":"Formuliere die geprüfte Regel und die ihr widersprechende gemeinsame Verpflichtung ausdrücklich.","formalRule":{"id":"III-11","page":4,"scope":"Bedingte indirekte Rekonstruktion, kein ausgeführter formaler Beweis","explanation":"Nimmt man «jeder kleine Einzelbeitrag ist unverpflichtend» sowie eine allgemeine Beitragsnorm an, hebt die beliebige Zerlegung jede gemeinsame Pflicht auf. Der Widerspruch setzt die Beitragsnorm voraus; sie ist nicht schon durch die Zerlegung bewiesen."},"role":"Argument der sprechenden Person"}}],"questions":["Welche gemeinsame Struktur trägt die Steueranalogie?","Welche Unterschiede zwischen verbindlichem Steuerstaat und globaler Klimakooperation bleiben?"],"teacher":"Die Analogie begründet eine Beitragsnorm, nicht die Wirksamkeit jeder konkreten Massnahme. Das formale Kleinheitsargument kann sonst jede kollektive Pflicht auflösen.","start":1526.04,"id":"s23","end":1607.76,"duration":81.72,"openingCueStart":1526.04},{"title":"Differenzierte Verantwortung und Leistungsfähigkeit","theme":"Gerechtigkeit","arguments":[{"speaker":"Knutti","claim":"Alle sollen beitragen, aber nicht alle im gleichen Umfang.","reason":"Er verweist auf gemeinsame, aber differenzierte Verantwortung in internationalen Vereinbarungen.","type":"Praktischer Schluss","id":"A067","family":"Praktischer Schluss","legacyType":"Norm- und Autoritätsargument","legacyFamily":"Autorität / Quellenbezug","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Gemeinsame Verantwortung kann durch ein anerkanntes Regelwerk differenziert ausgestaltet werden.","assessment":"Der Vertragsverweis zeigt einen institutionellen Normbezug, nicht allein die philosophische Richtigkeit jeder Verteilung.","fallacyChecks":[{"id":"V-07","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Ein einschlägiger Verweis auf geltende Vereinbarungen ist nicht automatisch ein unzulässiger Autoritätsappell.","page":6}],"verification":"Trenne Vertragsinhalt, Verbindlichkeit und eigenständige moralische Rechtfertigung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Leistungsfähigere Akteure sollen überproportional beitragen.","reason":"Die Steuerprogression illustriert eine nach Leistungsfähigkeit abgestufte Last.","type":"Analogieschluss · Praktischer Schluss","id":"A068","family":"Analogieschluss","legacyType":"Analogie und Norm","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wer mehr leisten kann, soll unter einer entsprechend begründeten Fairnessnorm einen grösseren Lastenanteil übernehmen.","assessment":"Steuerprogression illustriert die Leistungsfähigkeitsnorm, begründet sie aber nicht allein durch ihre Existenz.","fallacyChecks":[{"id":"IX-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die gleiche progressive Formel darf nicht ohne Zusatzargument vom Steuerstaat auf internationale Beiträge übertragen werden.","page":13}],"verification":"Begründe die Progression und berücksichtige unterschiedliche institutionelle Zuständigkeiten.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Reiche, technologisch starke und historisch verantwortliche Staaten sollen vorangehen.","reason":"Fähigkeit und vergangene Verursachung werden als zusätzliche Verpflichtungsgründe verbunden.","type":"Praktischer Schluss","id":"A069","family":"Praktischer Schluss","legacyType":"Kumulatives normatives Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Leistungsfähigkeit und historische Verursachung sollen bei der Zuteilung gemeinsamer Pflichten zählen.","assessment":"Mehrere normative Gründe werden kumuliert. Eine zwingende konkrete Priorität folgt erst nach Gewichtung und empirischer Zurechnung.","fallacyChecks":[{"id":"IX-01","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Wertprämissen sind rekonstruierbar; entscheidend ist ihre Rechtfertigung statt eines pauschalen Sein-Sollen-Vorwurfs.","page":12}],"verification":"Trenne aktuelle Fähigkeit, historische Verursachung und konkrete Höhe des geforderten Beitrags.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Trenne Verursacherprinzip, Leistungsfähigkeitsprinzip und historische Verantwortung.","Reicht der Verweis auf einen Vertrag zur moralischen Rechtfertigung der Verteilungsregel?"],"teacher":"Ein geltender Vertrag erklärt institutionelle Verbindlichkeit; die moralische Begründung der Regel benötigt weitere Werte. Nicht alle drei Prinzipien führen zwingend zu derselben Lastenverteilung.","start":1607.76,"id":"s24","end":1661.28,"duration":53.52,"openingCueStart":1607.76},{"title":"Globale Verletzlichkeit und ungleiche Anpassungsmöglichkeiten","theme":"Gerechtigkeit","arguments":[{"speaker":"Bleisch","claim":"Bedürftigkeit und fehlende Eigenverantwortung können eine internationale Hilfspflicht begründen.","reason":"Sie vergleicht Klimarisiken mit globaler Armut und fehlender medizinischer Grundversorgung.","type":"Analogieschluss · Praktischer Schluss","id":"A070","family":"Analogieschluss","legacyType":"Moralische Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Existenzielle unverschuldete Not und zumutbare Hilfsfähigkeit können eine Hilfspflicht begründen.","assessment":"Der Vergleich mit Armut erschliesst einen normativen Bezug; er ersetzt keine genaue Rechtsprüfung der behaupteten Zuständigkeit.","fallacyChecks":[{"id":"V-12","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Leiden ist bei einer Hilfspflicht sachlich relevant und deshalb nicht schon ein Appell an Mitleid.","page":7}],"verification":"Begründe die Hilfsnorm und prüfe den genauen rechtlichen Anspruch unabhängig von der Analogie.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Leistungsfähigkeit verpflichtet angesichts ungleicher Klimabetroffenheit besonders.","reason":"Land- und Trinkwasserverlust treffen Menschen, die sich Anpassung kaum leisten können.","type":"Praktischer Schluss","id":"A071","family":"Praktischer Schluss","legacyType":"Gerechtigkeitsargument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wer besonders helfen kann, soll existenziell gefährdeten Menschen unter einer Zumutbarkeitsnorm stärker beistehen.","assessment":"Die normative Schlussregel verbindet Verletzlichkeit und Leistungsfähigkeit. Ihre Reichweite ist strittig, aber kein formaler Fehler allein wegen des Sollens.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Pflicht wäre nicht allein aus einer Beschreibung ungleicher Betroffenheit ableitbar.","page":12}],"verification":"Nenne die Schutz- und Zumutbarkeitsnorm sowie Verteilungsgrenzen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Private Anpassung wohlhabender Menschen löst das globale Problem nicht.","reason":"Eine Klimaanlage ist für ärmere oder existenziell betroffene Menschen keine entsprechende Option.","type":"Dialektischer Schluss · Analogieschluss","id":"A072","family":"Dialektischer Schluss","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-04","page":2}],"implicitPremise":"Eine nur für Wohlhabende verfügbare Anpassung ist kein allgemein gleichwertiger Ersatz für globale Schadensvermeidung.","assessment":"Der Gegenfall begrenzt die Übertragbarkeit privater Anpassung auf existenzielle globale Risiken.","fallacyChecks":[{"id":"VI-09","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Aus der Anpassungsfähigkeit einer wohlhabenden Gruppe folgt nicht die Anpassungsfähigkeit aller Betroffenen.","page":8}],"verification":"Vergleiche konkrete Risiken statt eine Klimaanlage als Lösung jedes Klimaschadens zu behandeln.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Verantwortung folgt aus Verursachung und welche aus Hilfsfähigkeit?","Belegt der Verweis auf Menschenrechte genau die behauptete Zuständigkeitsregel?"],"teacher":"Die juristische Aussage zur Menschenrechtsdeklaration wird im Gespräch nicht belegt. Nicht als bestätigte Rechtsauskunft übernehmen. Die normative Argumentation lässt sich davon getrennt prüfen.","start":1661.28,"id":"s25","end":1721.08,"duration":59.8,"openingCueStart":1661.28},{"title":"Gerechtigkeit und politischer Erfolg sind verschiedene Fragen","theme":"Gerechtigkeit","arguments":[{"speaker":"Knutti","claim":"Eine Lastenverteilungsdebatte allein ist politisch nicht hinreichend erfolgreich.","reason":"Er führt das Scheitern von Kopenhagen 2009 als Erfahrung an.","type":"Induktion (verallgemeinernd) · Abduktion (Schluss auf die beste Erklärung)","id":"A073","family":"Induktion (verallgemeinernd)","legacyType":"Historisches Erfolgsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-03","page":1}],"implicitPremise":"Das Scheitern einer gerechtigkeitsorientierten Verhandlung kann auf begrenzte politische Durchsetzbarkeit dieser Strategie hinweisen.","assessment":"Kopenhagen ist ein Erfahrungsfall für eine Erklärungshypothese; es widerlegt die Norm der Gerechtigkeit nicht.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine Konferenz trägt keine universelle These über die Wirkungslosigkeit aller Gerechtigkeitsverhandlungen.","page":9},{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Das Konferenzscheitern kann mehrere Ursachen haben.","page":11}],"verification":"Vergleiche weitere Verhandlungen und trenne politische Wirksamkeit von moralischer Geltung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Nationale Selbstverpflichtungen sind ein pragmatischer Ausweg aus internationaler Blockade.","reason":"Staaten wollen sich nicht von anderen verbindliche Beiträge vorschreiben lassen.","type":"Praktischer Schluss · Abduktion (Schluss auf die beste Erklärung)","id":"A074","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-03","page":1}],"implicitPremise":"Wenn eine verbindliche Verteilung blockiert ist, können selbstbestimmte Beiträge einen pragmatischen Kooperationsweg eröffnen.","assessment":"Der praktische Schluss beruht auf einer politischen Erklärung der Blockade und einer Abwägung realer Alternativen.","fallacyChecks":[{"id":"VIII-10","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Eine unvollkommene Kooperationsform ist nicht schon deshalb wertlos, weil sie kein ideales System erreicht.","page":12}],"verification":"Vergleiche tatsächliche Wirkung und Ambitionsniveau verbindlicher und selbstbestimmter Modelle.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eigenvorteil kann auch ohne Einigung über Gerechtigkeit zum Handeln motivieren.","reason":"Wenn Staaten finanziell profitieren, haben sie einen eigenständigen Anreiz.","type":"Kausaler Schluss · Praktischer Schluss","id":"A075","family":"Kausaler Schluss","legacyType":"Nutzenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Eigeninteresse kann einen eigenständigen Handlungsanreiz liefern, auch ohne Einigung über die letzte moralische Begründung.","assessment":"Die Motivationshypothese ist mit einer Gerechtigkeitsnorm vereinbar; politischer Nutzen beweist keine moralische Wahrheit.","fallacyChecks":[{"id":"V-18","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Frage, was Menschen motiviert, wird nicht als Wahrheitsbeweis für eine Klimaaussage benutzt.","page":7}],"verification":"Prüfe, für welche Akteure welcher Nutzen tatsächlich entsteht und wer Nachteile trägt.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Widerlegt politisches Scheitern eine moralische Norm?","Ist Kopenhagen ein hinreichender Beleg für die generelle Wirkungslosigkeit von Gerechtigkeitsargumenten?"],"teacher":"Knutti sagt «nicht nur». Er verwirft damit nicht zwangsläufig Gerechtigkeit, sondern deren ausschliessliche Rolle als politischer Motor. Monokausale Erklärungen des Konferenzscheiterns wären zu stark.","start":1721.08,"id":"s26","end":1790.56,"duration":69.48,"openingCueStart":1721.08},{"title":"Rostalski-Einspieler: das Preis- und Verlagerungsargument","theme":"Kosten und Technik","arguments":[{"speaker":"Rostalski, Einspieler","claim":"Ein europäischer Alleingang könnte über den Weltmarkt teilweise kompensiert werden.","reason":"Geringere europäische Nachfrage soll fossile Preise senken und anderswo zusätzliche Nachfrage auslösen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A076","family":"Kausaler Schluss","legacyType":"Kausalkette","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Bei entsprechender Angebots- und Nachfrageelastizität kann geringere Nachfrage einer Region den Weltmarktpreis und den Verbrauch anderer verändern.","assessment":"Der Mechanismus ist als Möglichkeit plausibel; Umfang und Vorzeichen des Nettoeffekts sind damit noch nicht bestimmt.","fallacyChecks":[{"id":"VIII-09","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Kette wäre unbegründet, wenn alle Zwischenschritte ohne Mechanismus und Mengenbezug als zwangsläufig dargestellt würden.","page":12}],"verification":"Schätze Preiselastizitäten, Angebotsreaktion und zusätzliche Nachfrage quantitativ.","formalRule":null,"role":"Argument im Einspieler"}},{"speaker":"Rostalski, Einspieler","claim":"Die Verlagerung könnte unter ungünstigen Bedingungen sogar zu höheren Gesamtemissionen führen.","reason":"Sie verbindet Mehrverbrauch mit geringeren Klimaschutzanforderungen und anderen technischen Standards.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A077","family":"Kausaler Schluss","legacyType":"Kontraproduktivitätsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Nur wenn zusätzlich ausgelöste Emissionen die eingesparten Emissionen übersteigen, steigt die globale Summe.","assessment":"Die starke Kontraproduktivitätsfolgerung benötigt mehr als die Existenz eines Verlagerungskanals.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus möglichem Mehrverbrauch anderswo folgt ohne Mengenvergleich kein sicherer globaler Emissionsanstieg.","page":12}],"verification":"Bilanzier eingesparte Mengen, Mehrnachfrage und unterschiedliche Emissionsintensitäten unter realistischen Szenarien.","formalRule":null,"role":"Argument im Einspieler"}},{"speaker":"Bleisch im Einspieler","claim":"Die zugespitzte Folgerung soll explizit gemacht werden.","reason":"Sie fragt nach, ob Verbrauch in Europa dann besser wäre als andernorts.","type":"Dialektischer Schluss","id":"A078","family":"Dialektischer Schluss","legacyType":"Schlussprüfung","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine strittige Kausalkette soll auf ihre tatsächlich beanspruchte Schlussfolgerung festgelegt werden.","assessment":"Die Nachfrage prüft und paraphrasiert die Konsequenz des Einspielers. Sie ist noch kein unabhängiger Beleg für diese Konsequenz.","fallacyChecks":[{"id":"V-23","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Frage wäre ein Strohmann, wenn sie aus einer begrenzten Verlagerungsthese eine pauschale Forderung nach europäischem Mehrverbrauch machte.","page":8}],"verification":"Lass die befragte Person Reichweite und Bedingungen ihrer Aussage bestätigen.","formalRule":null,"role":"Argument im Einspieler"}}],"questions":["Schreibe alle Glieder der Kausalkette einzeln auf.","Unter welchen Preiselastizitäten, Mengenreaktionen und Emissionsintensitäten folgt tatsächlich ein globaler Anstieg?"],"teacher":"Ein möglicher Preiskanal ist nicht automatisch ein Nachweis vollständiger oder überkompensierender Verlagerung. Die Hypothese braucht quantitative Annahmen. Den Einspieler nicht der Moderatorin oder Knutti zuschreiben.","start":1790.56,"id":"s27","end":1864.92,"duration":74.36,"openingCueStart":1790.56},{"title":"Pferdeanalogie: begrenzter Bedarf und technische Substitution","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Sinkende Preise erzeugen nicht unbegrenzt zusätzliche Nachfrage.","reason":"Er karikiert die Annahme durch den Kauf eines zusätzlichen Pferds.","type":"Analogieschluss · Transduktiver Schluss","id":"A079","family":"Analogieschluss","legacyType":"Reductio und Analogie","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-13","page":2}],"implicitPremise":"Gesättigter oder substituierbarer Bedarf zeigt, dass ein niedrigerer Preis nicht unbegrenzt zusätzliche Nutzung erzeugen muss.","assessment":"Die Pferdegeschichte ist eine Analogie und Einzelfallübertragung. Sie zeigt keinen logischen Widerspruch und ist deshalb kein strenger Reductio-Beweis.","fallacyChecks":[{"id":"V-19","status":"rhetorik","label":"Rhetorischer Effekt – kein alleiniger logischer Nachweis","reason":"Die komische Pferdeszene kann Lächerlichkeit erzeugen, ohne alle behaupteten Weltmarktmechanismen zu widerlegen.","page":7},{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein veraltetes Verkehrsmittel ist nur eingeschränkt mit dem gesamten fossilen Energiemarkt vergleichbar.","page":12}],"verification":"Überführe die Pointe in überprüfbare Annahmen zu Sättigung, Substitution und Preiselastizität.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Ein gesättigter Wärmebedarf begrenzt die Nachfrage nach zusätzlicher Heizleistung.","reason":"Billigeres Öl macht eine zweite Heizung nicht nötig.","type":"Transduktiver Schluss · Analogieschluss","id":"A080","family":"Transduktiver Schluss","legacyType":"Bedarfsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-13","page":2},{"id":"I-04","page":2}],"implicitPremise":"Aus begrenztem Wärmebedarf eines Haushalts könnte unter ähnlichen Bedingungen begrenzter zusätzlicher fossiler Verbrauch folgen.","assessment":"Der Haushaltsfall stützt eine begrenzte Sättigungsthese, nicht die generelle Abwesenheit weltweiter Nachfrageeffekte.","fallacyChecks":[{"id":"VII-12","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Von einem individuellen Heizbedarf auf die Gesamtmarktreaktion zu schliessen wäre ein atomistischer Fehlschluss.","page":10}],"verification":"Untersuche zusätzliche Nutzung, neue Kunden, Industriebedarf und bestehende ungedeckte Nachfrage.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine bessere Alternative kann Nachfrage nach dem alten Gut verdrängen.","reason":"Er setzt Wärmepumpen und verschwundene Pferdenutzung als Beispiele ein.","type":"Kausaler Schluss · Analogieschluss · Prädiktiver Schluss","id":"A081","family":"Kausaler Schluss","legacyType":"Substitutionsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-04","page":2},{"id":"I-07","page":2}],"implicitPremise":"Bessere Substitute können Nachfrage von einer älteren Technik abziehen, auch wenn deren Preis sinkt.","assessment":"Ein plausibler Substitutionsmechanismus wird durch historische und technische Beispiele illustriert.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Pferdeersatz und weltweiter Energiemix unterscheiden sich in Infrastruktur, Zeithorizont und Einsatzfeldern.","page":12}],"verification":"Nenne Bedingungen, unter denen die Alternative tatsächlich überlegen und zugänglich ist.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Annahme des Einspielers trifft die Pferdeanalogie?","Darf man vom Heizbedarf eines Haushalts auf industrielle Nachfrage weltweit schliessen?"],"teacher":"Knuttis Analogien illustrieren Nachfragebegrenzung und Substitution. Sie widerlegen nicht sämtliche Preisreaktionen, etwa zusätzliche Nutzung oder wachsenden Bedarf in anderen Ländern. Beide Positionen bleiben empirisch zu prüfen.","start":1864.92,"id":"s28","end":1922.92,"duration":58.0,"openingCueStart":1864.92},{"title":"Indien als Gegenbeispiel und Problem der Bezugsgrössen","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Länder können fossile Nachfrage auch bei sinkenden Preisen durch bessere Alternativen ersetzen.","reason":"Er behauptet langfristige Vorteile der Alternativen und Nachteile der Kohle.","type":"Prädiktiver Schluss · Defeasibles (aufhebbares) Schliessen","id":"A082","family":"Prädiktiver Schluss","legacyType":"Substitutionsprognose","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-09","page":2}],"implicitPremise":"Wenn Alternativen unter vergleichbaren Bedingungen günstiger und geeigneter werden, kann fossile Nachfrage zurückgehen.","assessment":"Als bedingte Prognose ist der Schluss aufhebbar. Die pauschale Aussage über alle Länder und Kohle ist stärker als die angeführten Gründe.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein möglicher langfristiger Trend wird unzulässig zwingend, wenn Annahmen und Unsicherheiten fehlen.","page":12}],"verification":"Unterscheide Länder, Anwendungen, bestehende Anlagen und Übergangsfristen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Der Ausbau neuer Technik ist nicht auf Europa beschränkt.","reason":"Indischer Solarzubau und ein genannter Elektro-Neuwagenanteil dienen als Gegenbeispiel.","type":"Induktion (verallgemeinernd) · Statistischer Schluss · Dialektischer Schluss","id":"A083","family":"Induktion (verallgemeinernd)","legacyType":"Statistisches Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-05","page":2},{"id":"I-14","page":2}],"implicitPremise":"Ein belegter Ausbau ausserhalb Europas widerlegt die pauschale Behauptung, nur Europa entwickle Alternativen.","assessment":"Ein Gegenbeispiel ist für die Existenzfrage relevant. Es widerlegt weder jede Verlagerung noch eine globale fossile Dominanz.","fallacyChecks":[{"id":"VI-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Wachstumsrate, Marktanteil und Fahrzeugkategorie dürfen in der Zahlendarstellung nicht vertauscht werden.","page":8}],"verification":"Verifiziere Jahr, Land, Nenner und Fahrzeugkategorie; trenne Solarzubau vom Anteil am Gesamtverbrauch.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die bessere Wettbewerbsfähigkeit sollte zum Kern der Kommunikation werden.","reason":"Eine wirtschaftliche Vorteilserzählung soll die Verzichtserzählung ersetzen.","type":"Praktischer Schluss","id":"A084","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Eine wahrheitsgemässe Darstellung realer Wettbewerbsvorteile kann als Mittel zur Beteiligung geeignet sein.","assessment":"Die Empfehlung ist praktisch; tatsächlicher Vorteil und kommunikative Wirksamkeit sind getrennte Voraussetzungen.","fallacyChecks":[{"id":"V-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Neuheit allein wäre keine Begründung, dass eine Technik besser oder ihre Erzählung angemessen ist.","page":7}],"verification":"Belege konkrete Vorteile und benenne Ausnahmen sowie Umstellungskosten.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Widerlegt ein Beispiel aus Indien die weltweite Verlagerungshypothese?","Welche Fahrzeugkategorie und welcher Nenner stecken im behaupteten Elektroanteil?"],"teacher":"Die Passage nennt auffällige Zahlen. Solarzubau ist eine Wachstumsrate, kein Anteil am Gesamtenergiesystem. Der Elektro-Neuwagenanteil muss nach Kategorie, Zeitraum und Land separat verifiziert werden; hier keine Richtigkeitsbestätigung.","start":1922.92,"id":"s29","end":1981.04,"duration":58.12,"openingCueStart":1922.92},{"title":"Technisch günstig, an der Kasse teuer?","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch","claim":"Geringere Technikkosten sind noch kein Beleg für niedrigere Endkundenpreise.","reason":"Sie verweist auf fossile Dominanz und eigene Erfahrungen mit Aufpreisen für erneuerbaren Strom.","type":"Dialektischer Schluss · Analogieschluss","id":"A085","family":"Dialektischer Schluss","legacyType":"Gegenbeispiel und Bezugsgrössenargument","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-04","page":2}],"implicitPremise":"Aus niedrigen Herstellungskosten folgt nicht ohne weitere Voraussetzungen ein niedriger Endkundentarif.","assessment":"Die Beobachtung eines Aufpreises begrenzt eine zu starke Preisaussage. Sie widerlegt nicht die Erzeugungskostenbehauptung selbst.","fallacyChecks":[{"id":"VI-05","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Nachfrage klärt den möglichen Bedeutungswechsel von technisch günstig zu günstig an der Kasse.","page":8}],"verification":"Vergleiche dieselbe Kostenstufe, Vertragsform und Leistungsqualität.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Technische Kosten und Konsumentenpreise können auseinanderfallen.","reason":"Nicht eingepreiste CO2-Schäden verzerren den Vergleich zwischen Alternativen.","type":"Kausaler Schluss · Dialektischer Schluss","id":"A086","family":"Kausaler Schluss","legacyType":"Externalitätenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-14","page":2}],"implicitPremise":"Wenn ein Preis externe Schäden nicht enthält, bildet er nicht die gesellschaftlichen Gesamtkosten ab.","assessment":"Die Externalität erklärt eine Differenz von Rechnungsarten, noch nicht jede konkrete Tarifentwicklung.","fallacyChecks":[{"id":"VI-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Private Preise, Erzeugungskosten und gesellschaftliche Kosten müssen in allen Prämissen unterscheidbar bleiben.","page":8}],"verification":"Ergänze Netz-, Abgaben- und Marktkomponenten sowie eine getrennte Schadensrechnung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche drei Grössen werden unterschieden: Herstellungskosten, Rechnungspreis und gesellschaftliche Gesamtkosten?","Was erklärt der Hinweis auf Externalitäten und was noch nicht?"],"teacher":"Ein höherer Ökostromtarif widerlegt nicht automatisch niedrigere Erzeugungskosten. Netze, Abgaben, Tarife und Vertragsbedingungen sind zusätzliche Vergleichsgrössen.","start":1981.04,"id":"s30","end":2025.92,"duration":44.88,"openingCueStart":1981.04},{"title":"CO2-Schäden und Verursacherprinzip","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Ein Emissionspreisvergleich ist ohne Schäden unvollständig.","reason":"Eine Tonne CO2 verursacht nach seiner Angabe erhebliche Schäden an anderen Orten und zu anderen Zeiten.","type":"Kausaler Schluss · Praktischer Schluss","id":"A087","family":"Kausaler Schluss","legacyType":"Externalitätenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Ein gesellschaftlicher Kostenvergleich soll zurechenbare Schäden an Dritten berücksichtigen.","assessment":"Der Schluss verbindet eine empirische Schadensannahme mit einer Kostenbewertungsnorm.","fallacyChecks":[{"id":"VII-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein einzelner Frankenwert darf Unsicherheit, Zeitbezug und Bewertungsannahmen nicht verdecken.","page":11}],"verification":"Gib Quelle, Bandbreite, Diskontsatz und erfasste Schäden an.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Wer Kosten verursacht, soll für sie aufkommen.","reason":"Die Abfallgebühr illustriert eine schon vertraute Verursacherregel.","type":"Analogieschluss · Praktischer Schluss","id":"A088","family":"Analogieschluss","legacyType":"Normative Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wer unter vergleichbaren Verantwortungsbedingungen eine Entsorgungslast erzeugt, soll deren Kosten tragen.","assessment":"Die Abfallgebühr illustriert eine normative Regel, ist aber kein alleiniger Beweis ihrer weltweiten Übertragbarkeit.","fallacyChecks":[{"id":"IX-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Lokale Abfallpflichten und globale CO2-Verantwortung verlangen eine begründete Kontextübertragung.","page":13}],"verification":"Erläutere Verursachungszurechnung, Zuständigkeit, Verteilung und Zumutbarkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die Verantwortung betrifft private Konsumhandlungen ebenso wie Firmen.","reason":"Ein Australienflug dient als Rechenbeispiel für nicht bezahlte Schäden.","type":"Deduktion · Praktischer Schluss","id":"A089","family":"Deduktion","legacyType":"Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-08","page":2}],"implicitPremise":"Wenn dieselbe Verursacherregel für alle relevanten Emissionen gilt, umfasst sie auch private Flüge.","assessment":"Die Anwendung einer allgemeinen Norm auf private Konsumfälle ist konditional deduktiv rekonstruierbar. Die Emissions- und Schadenszahlen bleiben empirisch.","fallacyChecks":[{"id":"VII-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine einfache Multiplikation macht unsichere Eingangsgrössen nicht exakt.","page":11}],"verification":"Trenne CO2-Menge, weitere Klimawirkungen, monetäre Schadensannahme und Zahlungsregel.","formalRule":{"id":"II-01","page":2,"scope":"Konditionale Norm-Anwendung","explanation":"P = private Flugemissionen verursachen nach der gewählten Bilanz relevante Schäden; P → Q = für alle so verursachten Schäden gilt die begründete Verursacherregel; bei P folgt Q. Die allgemeine Norm und die Schadensprämisse müssen zusätzlich gestützt werden."},"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Schadensschätzungen müssen als Bandbreite statt als exakte Zahl behandelt werden.","reason":"Gesundheits-, Landwirtschafts-, Hochwasser- und Meeresspiegelrisiken sowie der Zeithorizont variieren.","type":"Defeasibles (aufhebbares) Schliessen · Dialektischer Schluss","id":"A090","family":"Defeasibles (aufhebbares) Schliessen","legacyType":"Unsicherheitsargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-09","page":2},{"id":"I-14","page":2}],"implicitPremise":"Bei unsicheren Parametern und mehreren Bewertungsannahmen ist eine Bandbreite angemessener als eine Scheingenauigkeit.","assessment":"Die Präzisierung begrenzt den Geltungsanspruch der Schätzung. Sie macht jede Zahl aber noch nicht methodisch zuverlässig.","fallacyChecks":[{"id":"VII-22","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Bandbreite reagiert auf das Risiko einer zu exakten Schadensangabe.","page":11}],"verification":"Belege, wie der Bereich zustande kommt und welche Schäden oder Zeithorizonte fehlen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche zusätzliche Norm macht aus verursachtem Schaden eine Zahlungspflicht?","Prüfe die Rechnung und benenne, welche Bilanzierung des Fluges vorausgesetzt ist."],"teacher":"Die Passage unterscheidet Schätzung und präzise Messung nicht immer sauber. Bandbreiten sind kein Beweis der Beliebigkeit. Emissionsmengen, Klimawirkungsfaktoren und monetäre Bewertung müssen getrennt belegt werden.","start":2025.92,"id":"s31","end":2107.52,"duration":81.6,"openingCueStart":2025.92},{"title":"Abfall, Abwasser und die vollständige Kostenrechnung","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Für CO2 soll dieselbe Verantwortungslogik gelten wie für Abfall und Abwasser.","reason":"Wer eine Entsorgung nötig macht, trägt sonst deren Kosten oder vermeidet sie.","type":"Analogieschluss · Praktischer Schluss","id":"A091","family":"Analogieschluss","legacyType":"Konsistenz- und Analogieargument","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Gleichartige Verantwortungsgründe sollen bei vergleichbaren Schäden konsistent behandelt werden.","assessment":"Der Analogie- und Konsistenzanspruch ist praktisch normativ; relevante Unterschiede können andere Instrumente rechtfertigen.","fallacyChecks":[{"id":"IX-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Identische Kosten- oder Entsorgungsregeln folgen nicht ohne Prüfung aus der Ähnlichkeit der Verursachung.","page":13}],"verification":"Vergleiche Erfassbarkeit, Dauerhaftigkeit, Grenzüberschreitung und Durchsetzbarkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Fossile Angebote können nur scheinbar günstiger sein.","reason":"Rechnet man externe Schäden hinzu, ändert sich der Kostenvergleich.","type":"Kontrafaktisches Schliessen · Praktischer Schluss","id":"A092","family":"Kontrafaktisches Schliessen","legacyType":"Kostenbilanzargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-11","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenn bisher ausgeblendete externe Kosten einbezogen würden, könnte sich die Rangfolge der Optionen ändern.","assessment":"Der kontrafaktische Rechnungsvergleich ist plausibel; eine bestimmte neue Rangfolge muss konkret berechnet werden.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die allgemeine Existenz externer Kosten garantiert nicht den Sieg jeder als alternativ bezeichneten Technik.","page":12}],"verification":"Vergleiche vollständige Lebenszyklus- und Schadenskosten beider Optionen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Kassenpreis und Gesamtbelastung können entgegengesetzte Rangfolgen zeigen.","reason":"Ein konventionelles und ein umweltfreundliches T-Shirt illustrieren den Unterschied.","type":"Analogieschluss","id":"A093","family":"Analogieschluss","legacyType":"Veranschaulichende Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2}],"implicitPremise":"Ein bekannter Warenvergleich kann den Unterschied zwischen privatem Preis und gesellschaftlicher Belastung erläutern.","assessment":"Das T-Shirt ist ein Erklärungsbeispiel der Rechnungslogik, kein eigenständiger Messbeleg für jede Energiealternative.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Übertragung wäre falsch, wenn unbewiesene Annahmen über jedes konventionelle oder faire Produkt mitübertragen würden.","page":12}],"verification":"Begrenze den Vergleich auf die mögliche Trennung von Preis und externer Wirkung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Wo endet die Übertragbarkeit der Abfallanalogie?","Ist das T-Shirt-Beispiel eine unabhängige Bestätigung oder eine Paraphrase des Arguments?"],"teacher":"Der T-Shirt-Vergleich erklärt die Logik, liefert aber keine Messung der konkreten Externalitäten. Die Behauptung politischer Abgabenaversion ist eine zusätzliche Verhaltensannahme.","start":2107.52,"id":"s32","end":2180.6,"duration":73.08,"openingCueStart":2107.52},{"title":"Vermeidungskosten und vorgezogene CO2-Entsorgungsgebühr","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Vermeidung kann wirtschaftlich günstiger sein als verursachter Schaden.","reason":"Er stellt genannte Schadenskosten von 500–1000 Franken oft niedrigeren Vermeidungskosten gegenüber.","type":"Praktischer Schluss · Deduktion","id":"A094","family":"Praktischer Schluss","legacyType":"Kostenvergleich","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-01","page":1}],"implicitPremise":"Wenn die Kosten einer konkreten Vermeidung unter den zurechenbaren Schäden liegen und weitere Bedingungen gleich sind, ist Vermeidung wirtschaftlich vorteilhaft.","assessment":"Die bedingte Vergleichsstruktur ist logisch nachvollziehbar; die genannten allgemeinen Zahlen machen sie nicht für jede Tonne wahr.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Einige günstige Vermeidungsmöglichkeiten begründen keine Aussage über alle Restemissionen.","page":9}],"verification":"Prüfe marginale Kosten, verfügbare Menge, Zeithorizont und zusätzliche Nebenfolgen.","formalRule":{"id":"II-01","page":2,"scope":"Konditional gültige Vergleichsstruktur","explanation":"P = die vollständigen Kosten einer bestimmten Vermeidung sind geringer als die vergleichbar bewerteten Schäden; P → Q = unter gleichen Nebenbedingungen ist Vermeidung im gewählten wirtschaftlichen Massstab vorteilhaft. Dann Q; P ist nicht für jede Tonne nachgewiesen."},"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"CO2-Entfernungskosten könnten bereits beim Kauf eingerechnet werden.","reason":"Eine vorgezogene Elektronik-Recyclinggebühr zeigt ein vertrautes Finanzierungsprinzip.","type":"Analogieschluss · Praktischer Schluss","id":"A095","family":"Analogieschluss","legacyType":"Instrumentenanalogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Eine verursachte künftige Entsorgungslast kann unter geeigneten Institutionen bereits beim Kauf finanziert werden.","assessment":"Die Elektronikgebühr zeigt ein mögliches Gestaltungsprinzip; technische und institutionelle Bedingungen müssen übertragen werden.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"CO2-Dauerhaftigkeit, Messung und globale Verantwortlichkeit können vom Elektronikrecycling abweichen.","page":12}],"verification":"Sichere tatsächliche Entfernung, Dauer, Finanzierung und Haftung vor einer pauschalen Gebührenregel.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Vollständige Preise könnten Verhalten zu Alternativen lenken.","reason":"Höhere fossile Kaufpreise schaffen einen finanziellen Wechselanreiz.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A096","family":"Kausaler Schluss","legacyType":"Anreizargument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Ein höherer relativer Preis kann unter erreichbaren Alternativen einen Wechselanreiz setzen.","assessment":"Der Mechanismus ist eine bedingte Verhaltensprognose, kein Automatismus für jede Person.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ohne Einkommens-, Zugangs- und Elastizitätsbedingungen ist eine sichere Wechselvorhersage zu stark.","page":12}],"verification":"Nenne Preiselastizität, Ausweichoptionen und soziale Verteilung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Ein Aufpreis kann auch die Bereitschaft zum Weiterkonsum mit Entfernung finanzieren.","reason":"Sie beschreibt die alternative Reaktion, gern mehr fürs spätere Aufräumen zu zahlen.","type":"Prädiktiver Schluss · Dialektischer Schluss","id":"A097","family":"Prädiktiver Schluss","legacyType":"Gegenprognose","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-14","page":2}],"implicitPremise":"Ein Preisaufschlag kann neben Vermeidung auch bezahlten Weiterkonsum auslösen.","assessment":"Die Gegenprognose erweitert die Fallmenge und widerlegt die Unvermeidbarkeit des Wechsels, nicht jede Lenkungswirkung.","fallacyChecks":[{"id":"IV-15","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Eine mögliche andere Reaktion darf weder als notwendige Reaktion noch als Ausschluss aller Lenkung ausgegeben werden.","page":6}],"verification":"Unterscheide Zahlungsbereitschaft von tatsächlicher zusätzlicher und dauerhafter Entfernung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Bedingungen machen die Recyclinganalogie tragfähig?","Führt der Aufpreis zwingend zu Vermeidung oder sind mehrere Verhaltensreaktionen möglich?"],"teacher":"Nicht jede Tonne lässt sich zu denselben Kosten vermeiden. Schaden, Vermeidung und Entfernung sind unterschiedliche Kostenbegriffe. Die Entfernung müsste technisch, mengenmässig und dauerhaft gesichert sein.","start":2180.6,"id":"s33","end":2243.48,"duration":62.88,"openingCueStart":2180.6},{"title":"Technologischer Optimismus als prüfbarer Einwand","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch, als Prüfthese","claim":"Neue Entfernungstechnologien könnten weitgehendes Weiterleben wie bisher erlauben.","reason":"Sie verweist auf Forschung, einen Nobelpreisträger und CO2-bindende Materialien.","type":"Prädiktiver Schluss · Praktischer Schluss","id":"A098","family":"Prädiktiver Schluss","legacyType":"Technik- und Autoritätsargument","legacyFamily":"Autorität / Quellenbezug","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Weiterkonsum wäre nur dann technisch vertretbar, wenn die zusätzlichen Emissionen wirksam, dauerhaft und im nötigen Massstab ausgeglichen werden könnten.","assessment":"Bleisch stellt eine Prüfthese vor. Der Verweis auf eine Technologie und Auszeichnung liefert diese Bedingungen noch nicht.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Technische Bindungsfähigkeit ist nicht hinreichend für eine skalierbare gesellschaftliche Lösung.","page":6},{"id":"V-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Nobelpreis ersetzt keine Prüfung von Kosten, Mengen und Dauerhaftigkeit.","page":6}],"verification":"Kennzeichne die These als zur Diskussion gestellt und prüfe ihre zusätzlichen Bedingungen.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Technik ist zentral, weil Wohlstand Energie benötigt.","reason":"Ohne Energie sinken gesellschaftliche Versorgungsmöglichkeiten und Lebensqualität.","type":"Praktischer Schluss · Kausaler Schluss","id":"A099","family":"Praktischer Schluss","legacyType":"Zweck-Mittel-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Wenn ein Versorgungsziel Energie voraussetzt, sind geeignete Energietechniken Mittel dieses Ziels.","assessment":"Der praktische Schluss macht die Rolle von Technik plausibel, beweist aber nicht denselben Energiebedarf für jede Form von Wohlstand.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine notwendige Voraussetzung wie Energie ist nicht bereits hinreichend für Wohlstand.","page":6}],"verification":"Bestimme Mindestversorgung, Effizienzpotential und weitere Wohlstandsbedingungen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Daraus folgt vor allem der Umbau der Energieversorgung.","reason":"Benötigte Energie sollte sauber und fossilfrei bereitgestellt werden, nicht bloss unverändert weitergenutzt werden.","type":"Praktischer Schluss","id":"A100","family":"Praktischer Schluss","legacyType":"Transformationsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wohlstand soll unter einer Klimaschutz- und Zumutbarkeitsnorm mit geringerer fossiler Belastung ermöglicht werden.","assessment":"Aus Energiebedarf allein folgt der fossilfreie Umbau nicht; die Schutz- und Vergleichsnorm muss ausdrücklich hinzukommen.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ohne ergänzte Klimaschutz- und Abwägungsnorm wäre die Pflicht nicht aus dem Energiebedarf ableitbar.","page":12}],"verification":"Formuliere Zielkonflikte und vergleiche sauberere Versorgung, Effizienz und veränderte Nachfrage.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Was ist ein Machbarkeitsbeleg und was ein Skalierbarkeitsbeleg?","Kann der Nobelpreis die politische Schlussfolgerung tragen?"],"teacher":"Bleisch stellt eine These zur Prüfung, statt sie zwingend selbst zu vertreten. Die wissenschaftliche Auszeichnung belegt nicht automatisch günstige, grossskalige und dauerhafte Entfernung.","start":2243.48,"id":"s34","end":2313.76,"duration":70.28,"openingCueStart":2243.48},{"title":"Restemissionen, Speicherung und Skalierungsgrenzen","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"CO2-Entfernung wird für schwer vermeidbare Restemissionen benötigt.","reason":"Er nennt Düngung, Fliegen, Zement und medizinische Anwendungen.","type":"Praktischer Schluss · Defeasibles (aufhebbares) Schliessen","id":"A101","family":"Praktischer Schluss","legacyType":"Ausnahme- und Zweckargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-09","page":2}],"implicitPremise":"Wenn bestimmte Restemissionen unvermeidbar bleiben und netto begrenzt werden sollen, braucht es geeignete zusätzliche Entfernung.","assessment":"Der praktische Schluss ist von der Restemissionsannahme und dem Nettoziel abhängig, nicht von pauschaler Unvermeidbarkeit ganzer Branchen.","fallacyChecks":[{"id":"VI-15","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Begründete Restemissionen dürfen nicht zu unbegründeten Ausnahmen für beliebige Emissionen werden.","page":9}],"verification":"Prüfe für jede Anwendung Vermeidungskosten, Alternativen und verbleibende Restmenge.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Technische Funktion beweist noch keine allgemeine wirtschaftliche Lösung.","reason":"Das isländische Beispiel sei teuer und mengenmässig klein.","type":"Dialektischer Schluss","id":"A102","family":"Dialektischer Schluss","legacyType":"Skalierungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Die technische Funktion einer Anlage ist nur eine notwendige Teilbedingung einer wirtschaftlich und mengenmässig ausreichenden Lösung.","assessment":"Die Unterscheidung von Funktion, Preis und Menge weist einen zu starken Technologiefreibrief zurück.","fallacyChecks":[{"id":"IV-16","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Szene bestreitet gerade die Gleichsetzung von Machbarkeit und hinreichender Gesamtlösung.","page":6}],"verification":"Belege Nettomenge, Energiebedarf, Kostenentwicklung und Dauerhaftigkeit separat.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Entfernung ist auch zum Rückgängigmachen historischer CO2-Anreicherung relevant.","reason":"Vermeidung allein holt bereits emittiertes CO2 nicht zurück.","type":"Kausaler Schluss · Praktischer Schluss","id":"A103","family":"Kausaler Schluss","legacyType":"Kausales Argument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Das Unterlassen neuer Emissionen beseitigt nicht von selbst den bereits aufgebauten atmosphärischen Bestand.","assessment":"Der Bestands-Fluss-Unterschied begründet den zusätzlichen Zweck von Entfernung. Ein exklusiver Lösungsanspruch braucht eine genaue Zieldefinition.","fallacyChecks":[{"id":"VI-03","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Rede von der einzigen Lösung wäre zu eng, wenn unterschiedliche Entfernungswege oder natürliche Prozesse ausgeschlossen würden.","page":8}],"verification":"Definiere Zielmenge und Zeithorizont und unterscheide Entfernungsmethoden sowie Senken.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Warum ist ein funktionierendes Pilotprojekt noch kein Freibrief für weitere Emissionen?","Unterscheide netto vermiedene, entfernte und dauerhaft gespeicherte Mengen."],"teacher":"Die Beispiele sind Sammelkategorien mit unterschiedlichen Emissionen. Die Gleichsetzung jeder medizinischen Klimawirkung mit CO2 wäre zu einfach. Auch «einzige Lösung» verlangt eine genaue Abgrenzung des Ziels.","start":2313.76,"id":"s35","end":2372.52,"duration":58.76,"openingCueStart":2313.76},{"title":"Ohne Bepreisung fehlt der Markt für Entfernung","theme":"Politik und Freiheit","arguments":[{"speaker":"Bleisch","claim":"CO2-Entfernung ist ohne Verpflichtung für viele Emittenten ökonomisch unattraktiv.","reason":"Unbepreistes Ausstossen ist privat billiger als bezahltes Einfangen.","type":"Kausaler Schluss · Prädiktiver Schluss","id":"A104","family":"Kausaler Schluss","legacyType":"Anreizargument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn Ausstoss privat billiger bleibt als Entfernung und keine andere Motivation greift, entsteht wenig finanzieller Entfernungsanreiz.","assessment":"Der Anreizmechanismus ist plausibel unter den genannten Bedingungen; freiwillige Nachfrage oder Haftungsrisiken können ihn modifizieren.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Alle Nachfrage nur auf eine fehlende CO2-Pflicht zurückzuführen blendet andere Geschäfts- und Regulierungsfaktoren aus.","page":11}],"verification":"Prüfe tatsächliche Preis-, Haftungs-, Förder- und Reputationsanreize.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Technische Möglichkeiten benötigen politische Rahmenbedingungen.","reason":"Das Unternehmensbeispiel und der fehlende Zahlungsanreiz zeigen eine Finanzierungslücke.","type":"Praktischer Schluss","id":"A105","family":"Praktischer Schluss","legacyType":"Zweck-Mittel-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wenn ein gesellschaftlich benötigtes Angebot privat nicht ausreichend finanziert wird, sollen geeignete Rahmenbedingungen geprüft werden.","assessment":"Die Finanzierungslücke begründet eine Instrumentensuche, nicht bereits die Alternativlosigkeit einer konkreten staatlichen Lösung.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein politischer Rahmen allein garantiert weder Nachfrage noch wirksame technische Entfernung.","page":6}],"verification":"Vergleiche Preise, Standards, Beschaffung und Forschungsförderung mit ihren Nebenwirkungen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Akteure haben einen privaten Anreiz und wer trägt die gesellschaftlichen Kosten?","Folgt aus der Finanzierungslücke genau ein bestimmtes politisches Instrument?"],"teacher":"Die konkrete Aussage über Subventionsentzug und Unternehmenslage wird nicht unabhängig bestätigt. Die allgemeinere Anreizstruktur kann getrennt davon untersucht werden.","start":2372.52,"id":"s36","end":2435.4,"duration":62.88,"openingCueStart":2372.52},{"title":"Anschub, Lernkurven und Trittbrettfahrer","theme":"Politik und Freiheit","arguments":[{"speaker":"Knutti","claim":"Neue Technik kann anfangs staatliche Unterstützung benötigen.","reason":"Anfangskosten können hoch sein, bevor grössere Stückzahlen und Lernen sie senken.","type":"Kausaler Schluss · Prädiktiver Schluss · Praktischer Schluss","id":"A106","family":"Kausaler Schluss","legacyType":"Dynamisches Kostenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenn Lernen und Skalierung an anfänglicher Unterfinanzierung scheitern, kann zeitlich begrenzte Förderung den späteren Nutzen ermöglichen.","assessment":"Die dynamische Begründung ist ein bedingter praktischer Schluss mit kausaler Lernhypothese.","fallacyChecks":[{"id":"VIII-14","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Anfangs teure Technik wird nicht notwendig durch Förderung günstig und erfolgreich.","page":12}],"verification":"Prüfe Lernkurve, Skalierbarkeit, Alternativkosten und Ausstiegskriterien der Förderung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Solarförderung illustriert möglichen Erfolg politischer Anschubhilfe.","reason":"Er verweist auf früher teure und heute erschwingliche Solartechnik.","type":"Induktion (verallgemeinernd) · Kausaler Schluss","id":"A107","family":"Induktion (verallgemeinernd)","legacyType":"Historisches Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-06","page":2}],"implicitPremise":"Ein historischer Förderfall kann Hinweise liefern, dass Anschubhilfe zur späteren Kostenreduktion beiträgt.","assessment":"Solar ist ein Erfahrungsbeispiel, keine alleinige Identifikation des Förderkausaleffekts und keine Garantie jeder Förderung.","fallacyChecks":[{"id":"VIII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus «Förderung zuerst, niedrige Kosten später» folgt ohne Zusatzbelege noch keine vollständige Kausalzuordnung.","page":11}],"verification":"Vergleiche geförderte und andere Entwicklungen sowie technische Fortschritte und Skaleneffekte.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Gemeinsame Regeln sollen Trittbrettfahren verhindern.","reason":"Ohne verbindliche Beiträge können einzelne vom Handeln anderer profitieren.","type":"Praktischer Schluss · Kausaler Schluss","id":"A108","family":"Praktischer Schluss","legacyType":"Kollektivgutargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Bei einem gemeinsamen Gut können unkoordinierte Akteure Anreize haben, Beiträge anderer auszunutzen; faire Regeln sollen dies begrenzen.","assessment":"Der praktische Schluss verbindet ein institutionelles Anreizproblem mit einer Beitragsnorm.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Regeln sind nicht schon wegen ihres Vorhandenseins hinreichend gegen jedes Trittbrettfahren.","page":6}],"verification":"Prüfe Reichweite, Durchsetzung, Schlupflöcher und faire Lastenverteilung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Verbote können den Umstieg auf Alternativen bewirken.","reason":"FCKW-Spraydosen dienen als Beispiel für regulatorisch erzwungene Ablösung.","type":"Analogieschluss · Kausaler Schluss","id":"A109","family":"Analogieschluss","legacyType":"Historische Analogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-06","page":2}],"implicitPremise":"Wenn ein reguliertes Produkt ersetzbar ist, können Verbote seine Verwendung wirksam beenden.","assessment":"FCKW illustriert regulatorische Wirkung; Klimapolitik verlangt wegen anderer Reichweite eine erneute Vergleichsprüfung.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Produktverbot ist nicht ohne Weiteres mit der gesamten fossilen Energieversorgung gleichzusetzen.","page":12}],"verification":"Vergleiche Alternativenverfügbarkeit, Kontrollierbarkeit und soziale Folgen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Information wäre nötig, um den Fördererfolg kausal zuzuordnen?","Welche Unterschiede zwischen FCKW und dem gesamten fossilen Energiesystem sind relevant?"],"teacher":"Anschubhilfe, Preissteuerung und Verbote sind verschiedene Instrumente. Das FCKW-Beispiel belegt nicht automatisch die Verhältnismässigkeit jedes Klimaverbots.","start":2435.4,"id":"s37","end":2503.0,"duration":67.6,"openingCueStart":2435.4},{"title":"Andere handeln nicht – warum soll ich?","theme":"Politik und Freiheit","arguments":[{"speaker":"Bleisch, als Einwand","claim":"Einzelne können ihren Beitrag als aussichtslos oder unfair empfinden.","reason":"Sie nimmt die vermeintliche Untätigkeit Chinas und der USA als verbreitete Rechtfertigung auf.","type":"Dialektischer Schluss · Praktischer Schluss","id":"A110","family":"Dialektischer Schluss","legacyType":"Kooperations- und Fairnesseinwand","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-08","page":2}],"implicitPremise":"Falls eigene Anstrengungen durch nachweisbare fehlende Kooperation wirkungslos oder unzumutbar wären, wäre die konkrete Pflicht zu prüfen.","assessment":"Bleisch bringt einen verbreiteten Einwand zur Diskussion. Die empirische Prämisse fremder Untätigkeit und ihre Reichweite sind nicht gesichert.","fallacyChecks":[{"id":"V-21","status":"pruefthese","label":"Vorgeführte Prüfthese – keine Zuschreibung als eigene Überzeugung","reason":"Whataboutism entsteht, wenn fremdes Fehlverhalten die eigene Prüfung ersetzen soll.","page":7},{"id":"IX-05","status":"pruefthese","label":"Vorgeführte Prüfthese – keine Zuschreibung als eigene Überzeugung","reason":"«Andere handeln falsch, also darf ich es auch» wäre ohne weitere Fairness- oder Wirksamkeitsprämissen kein tragfähiger Schluss.","page":13}],"verification":"Trenne legitime Kooperationsanalyse, behauptete Aussichtslosigkeit und blosse Ablenkung.","formalRule":null,"role":"Vorgeführter Einwand / Prüfthese"}},{"speaker":"Knutti","claim":"Die behauptete Belastung ist nicht bei jeder Massnahme ein Verzicht.","reason":"Ein Elektroauto könne dieselbe Mobilität mit Komfortvorteilen erfüllen.","type":"Dialektischer Schluss","id":"A111","family":"Dialektischer Schluss","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Ein belegter Fall gleichen Nutzens mit Vorteilen genügt, um jede Massnahme als zwingenden Verzicht zu bestreiten.","assessment":"Das E-Auto kann ein Gegenbeispiel sein; es widerlegt nicht jede individuelle Belastung oder den vorausgehenden Kooperationseinwand.","fallacyChecks":[{"id":"V-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Komfortvorteil beantwortet nicht unmittelbar die Frage globaler Wirksamkeit und Kooperation.","page":8}],"verification":"Begrenze die Widerlegung auf die pauschale Verzichtsthese und bearbeite die übrigen Einwände getrennt.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Trenne die Wirksamkeitsfrage von der Fairnessfrage.","Welche frühere Argumentation zur Kleinheit und Steuerpflicht passt zu diesem Einwand?"],"teacher":"Bleisch präsentiert einen verbreiteten Einwand. Ihn allein als Whataboutism abzutun wäre zu grob: Unter bestimmten Bedingungen ist die Frage nach Kooperation und Wirksamkeit sachlich relevant.","start":2503.0,"id":"s38","end":2550.68,"duration":47.68,"openingCueStart":2503.0},{"title":"E-Auto: Anschaffungskosten, Lebenszyklus und Zugang","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch","claim":"Ein individuell sinnvoller Umstieg kann an Anfangskosten und Infrastruktur scheitern.","reason":"Sie nennt Fahrzeugpreis, fehlende Steckdose und Ladegelegenheiten.","type":"Praktischer Schluss · Defeasibles (aufhebbares) Schliessen","id":"A112","family":"Praktischer Schluss","legacyType":"Zumutbarkeitsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-09","page":2}],"implicitPremise":"Eine Empfehlung muss für Betroffene finanziell und praktisch ausführbar sein.","assessment":"Anfangskosten und fehlende Ladegelegenheit sind relevante Nebenbedingungen eines praktischen Schlusses, keine blosse Stimmung gegen Technik.","fallacyChecks":[{"id":"VI-09","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Aus durchschnittlicher Vorteilhaftigkeit folgt nicht die individuelle Leistbarkeit jedes Umstiegs.","page":8}],"verification":"Prüfe Liquidität, Miet- und Infrastrukturbedingungen sowie geeignete Ausgleichsmittel.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Der Anschaffungspreis allein unterschätzt mögliche Kostenvorteile.","reason":"Er verweist auf geringere Betriebskosten über den Lebenszyklus.","type":"Deduktion · Praktischer Schluss","id":"A113","family":"Deduktion","legacyType":"Lebenszyklusargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-08","page":2}],"implicitPremise":"Wenn vergleichbare Gesamtkosten über dieselbe Nutzungsdauer niedriger sind, ist die Alternative in diesem Lebenszyklusvergleich günstiger.","assessment":"Die bedingte Kostenstruktur ist logisch nachvollziehbar; ihre Eingangsdaten und Übertragbarkeit sind nicht damit bewiesen.","fallacyChecks":[{"id":"V-22","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine günstige Gesamtsumme erledigt die Frage fehlenden Anfangskapitals nicht.","page":8}],"verification":"Lege Kaufpreis, Finanzierung, Fahrleistung, Energiepreise, Wartung und Restwert offen.","formalRule":{"id":"II-01","page":2,"scope":"Konditional gültige Begriffsanwendung","explanation":"Wenn eine vergleichbar abgegrenzte Lebenszyklusrechnung geringere Gesamtkosten ausweist, ist die Option in genau diesem Kostenvergleich günstiger. Ob die Rechnung stimmt und die Person die Anfangsinvestition tragen kann, sind andere Fragen."},"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Politische Rahmenbedingungen können Zugangshürden abbauen.","reason":"Ein Recht auf Laden und geeignete Stromanschlüsse sollen einen Wechsel ermöglichen.","type":"Praktischer Schluss · Kausaler Schluss","id":"A114","family":"Praktischer Schluss","legacyType":"Zweck-Mittel-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Wenn Infrastrukturmangel einen sinnvollen Wechsel blockiert, kann die Beseitigung dieses Mangels Zugang ermöglichen.","assessment":"Die Empfehlung ist zielbezogen und kausal bedingt; ein Recht allein garantiert noch nicht jede technische Umsetzung.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Rechtlicher Anspruch, tatsächlicher Anschluss und erfolgreicher Umstieg sind verschiedene Bedingungen.","page":6}],"verification":"Prüfe technische Kapazität, Kostenverteilung, Umsetzung und Alternativen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Ladezugang kann als grundlegende Infrastruktur verstanden werden.","reason":"Der Wasseranschluss dient als Vergleich für erwartbare Gebäudeversorgung.","type":"Analogieschluss · Praktischer Schluss","id":"A115","family":"Analogieschluss","legacyType":"Infrastrukturanalogie","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Grundlegende Versorgungsfunktionen können einen geregelten Gebäudezugang rechtfertigen.","assessment":"Der Wasservergleich stützt eine Infrastrukturnorm, legt aber weder identische Technik noch automatisch identische Rechte fest.","fallacyChecks":[{"id":"IX-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine beim Wasser begründete Pflicht darf nicht ohne Prüfung unverändert auf Ladestrom übertragen werden.","page":13}],"verification":"Vergleiche Notwendigkeit, Leistungsbedarf, Zuständigkeit und Verhältnismässigkeit.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Löst eine günstige Lebenszyklusrechnung das Problem fehlender Liquidität?","Welche Kosten, Nutzungsdauer und Fahrleistung muss die Rechnung einschliessen?"],"teacher":"Die Einwände zu Kapital und Zugang sind nicht schon durch geringere Betriebskosten widerlegt. Wasser- und Ladeanschluss haben Gemeinsamkeiten, aber auch technische und mietrechtliche Unterschiede.","start":2550.68,"id":"s39","end":2626.48,"duration":75.8,"openingCueStart":2550.68},{"title":"China und die Innovationsdiagnose","theme":"Kosten und Technik","arguments":[{"speaker":"Knutti","claim":"Die pauschale Behauptung chinesischer Untätigkeit ist unzutreffend.","reason":"Er verweist auf aggressive Investitionen und den Vorsprung bei neuer Automobiltechnik.","type":"Induktion (verallgemeinernd) · Dialektischer Schluss","id":"A116","family":"Induktion (verallgemeinernd)","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-14","page":2}],"implicitPremise":"Ein belegter relevanter Technologiewechsel in China widerlegt die pauschale Aussage, China tue in diesem Bereich nichts.","assessment":"Der Gegenfall ist auf den genannten Sektor beschränkt und bestätigt nicht die gesamte Klimapolitik oder Bilanz des Landes.","fallacyChecks":[{"id":"VI-09","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein Fortschritt im Automobilbereich darf nicht jedem Sektor oder der gesamten Klimabilanz zugeschrieben werden.","page":8}],"verification":"Belege den Sektorfortschritt und trenne ihn von Gesamtenergie- und Emissionstrends.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Probleme der deutschen Autoindustrie erklärt er durch verpasste Innovation statt Umweltschutz.","reason":"Chinas Vorsprung wird als konkurrierende Kausalerklärung angeführt.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A117","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausale Gegenhypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Ein Innovationsrückstand kann Wettbewerbsprobleme erklären und ist gegen die Umweltschutz-Erklärung zu prüfen.","assessment":"Die Aussage bietet eine konkurrierende Ursache, weist aber nicht nach, dass nur diese wirkt.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"«Nicht Umweltschutz, sondern nur verpasste Innovation» kann Mehrfachursachen unzulässig ausschliessen.","page":11}],"verification":"Vergleiche Investitionen, Nachfrage, Regulierung, Standort- und Handelsfaktoren.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Daten unterscheiden die konkurrierenden Erklärungen?","Kann ein Innovationsvorsprung die gesamte Klimabilanz eines Landes belegen?"],"teacher":"Die Formulierung zur praktisch toten Autoindustrie ist eine starke Übertreibung. Auch die Gegenhypothese braucht Belege und darf Mehrfachursachen nicht ausschliessen.","start":2626.48,"id":"s40","end":2651.08,"duration":24.6,"openingCueStart":2626.48},{"title":"Whataboutism und Foers Plädoyer für einen Plan","theme":"Politik und Freiheit","arguments":[{"speaker":"Bleisch","claim":"Ständige Verweise auf jeweils andere Probleme können Handeln blockieren.","reason":"Nach jeder Handlung wird eine neue persönliche Inkonsistenz thematisiert.","type":"Dialektischer Schluss · Kausaler Schluss","id":"A118","family":"Dialektischer Schluss","legacyType":"Diskursdiagnose","legacyFamily":"Problemaufriss / Diskurskritik","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-06","page":2}],"implicitPremise":"Ein sachlich unabhängiger Verweis auf weitere Fehler widerlegt den geprüften Handlungsgrund nicht und kann den Diskurs blockieren.","assessment":"Bleisch beschreibt und kritisiert ein Muster; es wird nicht ihr selbst als verwendeter Fehlschluss zugeschrieben.","fallacyChecks":[{"id":"V-21","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Das jeweils neue Fremdproblem soll die ursprüngliche Prüfung nicht verdrängen.","page":7},{"id":"V-02","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Persönliche Inkonsistenz macht ein Sachargument nicht ohne Weiteres falsch.","page":6}],"verification":"Zeige am konkreten Kontext, ob der nächste Hinweis relevant ist oder die Streitfrage nur verschiebt.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Foer, Einspieler","claim":"Ein persönlicher Plan kann Gewohnheiten durchbrechen.","reason":"Ohne Vorsatz würden Menschen meist tun, was sie und andere bisher getan haben.","type":"Kausaler Schluss · Praktischer Schluss","id":"A119","family":"Kausaler Schluss","legacyType":"Kausales Handlungsargument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-06","page":2},{"id":"I-08","page":2}],"implicitPremise":"Ein vorher gefasster begrenzter Vorsatz kann Gewohnheitsschritte verändern und deshalb als Handlungshilfe sinnvoll sein.","assessment":"Foers Anekdote illustriert einen möglichen Mechanismus, liefert aber keine repräsentative Wirksamkeitsschätzung.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Geschichte eines Paares wäre anekdotischer Beweis, falls sie die allgemeine Wirksamkeit ersetzen soll.","page":9}],"verification":"Prüfe Einhaltung, Dauer und Vergleich mit Personen ohne solchen Plan.","formalRule":null,"role":"Argument im Einspieler"}},{"speaker":"Foer, Einspieler","claim":"Wer von Institutionen Pläne erwartet, sollte auch das eigene Handeln prüfen.","reason":"Er beschreibt die Diskrepanz zwischen seinen öffentlichen Erwartungen und seinem fehlenden eigenen Plan.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A120","family":"Praktischer Schluss","legacyType":"Konsistenzargument","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Wer einen Standard begründet fordert, soll dessen mögliche Anwendung auf das eigene Handeln reflektieren.","assessment":"Der Konsistenzappell ist eine Aufforderung zur Selbstprüfung, keine Widerlegung institutioneller Pflichten wegen eigener Unvollkommenheit.","fallacyChecks":[{"id":"V-02","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Es wäre tu quoque, wenn fehlende Eigenplanung die Forderung nach staatlichen Plänen allein widerlegen sollte.","page":6}],"verification":"Begründe persönliche und institutionelle Pflichten jeweils für sich und prüfe ihr Verhältnis.","formalRule":null,"role":"Argument im Einspieler"}},{"speaker":"Foer, Einspieler","claim":"Ein praktikabler Plan kann konkrete, begrenzte Regeln enthalten.","reason":"Das Paar benennt Ernährung und Mobilität mit situativen Ausnahmen.","type":"Induktion (verallgemeinernd) · Praktischer Schluss","id":"A121","family":"Induktion (verallgemeinernd)","legacyType":"Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-08","page":2}],"implicitPremise":"Ein konkret formulierter Plan mit Ausnahmen kann zeigen, dass ein solcher Regeltyp praktisch vorstellbar ist.","assessment":"Das Paar illustriert eine Möglichkeit, nicht allgemeine Zumutbarkeit oder zuverlässige Befolgung.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Ein praktikabel klingender Einzelfall belegt nicht, dass dieselben Regeln für alle geeignet sind.","page":9}],"verification":"Trenne Planinhalt, tatsächliche Umsetzung und die Lebensbedingungen unterschiedlicher Personen.","formalRule":null,"role":"Argument im Einspieler"}}],"questions":["Wann ist ein Inkonsistenzhinweis relevant und wann lenkt er vom Sachargument ab?","Kann die Anekdote zeigen, dass solche Pläne allgemein funktionieren?"],"teacher":"Foers Erzählung illustriert eine Möglichkeit, ist aber keine repräsentative Wirksamkeitsstudie. Die genannten Lebensregeln sind seine Beispiele und keine Lernvorgaben.","start":2651.08,"id":"s41","end":2783.72,"duration":132.64,"openingCueStart":2651.08},{"title":"Kahneman: begrenzte Planungskapazität","theme":"Politik und Freiheit","arguments":[{"speaker":"Knutti","claim":"Nicht jeder kann alle Klimahandlungen bewusst durchplanen.","reason":"Bauchgefühl, Gewohnheiten und soziale Orientierung bestimmen viele Entscheidungen.","type":"Induktion (verallgemeinernd) · Kausaler Schluss · Defeasibles (aufhebbares) Schliessen","id":"A122","family":"Induktion (verallgemeinernd)","legacyType":"Verhaltensargument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-06","page":2},{"id":"I-09","page":2}],"implicitPremise":"Begrenzte Aufmerksamkeit und routinierte Entscheidungen beschränken die Möglichkeit umfassender bewusster Planung.","assessment":"Die Berufung auf ein Verhaltensmodell kann einen empirischen Schluss stützen, ersetzt aber dessen genaue Beschreibung und Evidenz nicht.","fallacyChecks":[{"id":"V-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Kahnemans Name wäre ein Autoritätsersatz, wenn sein Modell und seine Reichweite nicht erklärt würden.","page":6}],"verification":"Unterscheide begrenzte Rationalität, nützliche Routinen und völlige Planungsunfähigkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Umfassende rationale Planung ist mental aufwendig.","reason":"Er veranschaulicht langsames Abwägen am seltenen Beispiel einer Auswanderungsentscheidung.","type":"Induktion (verallgemeinernd) · Analogieschluss","id":"A123","family":"Induktion (verallgemeinernd)","legacyType":"Belastungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-04","page":2}],"implicitPremise":"Eine seltene bewusst abgewogene Lebensentscheidung illustriert den Aufwand langsamer Planung.","assessment":"Der Auswanderungsfall veranschaulicht eine Belastung, misst sie aber nicht und beweist keine universelle Grenze.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Illustration würde zur unzulässigen Evidenz, wenn sie jede systematische Untersuchung ersetzte.","page":9}],"verification":"Vergleiche Aufwand einfacher Vorsätze mit komplexer Einzeloptimierung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine allgemeine Strategie darf nicht dauernde bewusste Planung voraussetzen.","reason":"Begrenzte Aufmerksamkeit und Motivation schränken die Übertragbarkeit individueller Pläne ein.","type":"Praktischer Schluss","id":"A124","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Eine allgemeine Verhaltensstrategie soll psychologisch zumutbar und mit begrenzter Aufmerksamkeit vereinbar sein.","assessment":"Der praktische Schluss benötigt die Zumutbarkeitsnorm. Aus Kapazitätsgrenzen folgt nicht, dass gar keine Planung erwartet werden darf.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die normative Begrenzung ist nicht allein eine Tatsachenfolge begrenzter Aufmerksamkeit.","page":12}],"verification":"Formuliere realistische Mindestanforderungen und institutionelle Unterstützung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Rolle spielt Kahnemans Name: Beleg, Modell oder Autoritätsersatz?","Widerlegt begrenzte Rationalität jeden sinnvollen persönlichen Vorsatz?"],"teacher":"Die Aussage «hochgradig irrational» ist eine grobe Zusammenfassung. Gewohnheiten können auch nützlich sein. Zwischen universeller Detailplanung und einigen einfachen Regeln bestehen Zwischenstufen.","start":2783.72,"id":"s42","end":2852.8,"duration":69.08,"openingCueStart":2783.72},{"title":"Ernährungspläne als Gegenbeispiel – und ihre Grenze","theme":"Politik und Freiheit","arguments":[{"speaker":"Bleisch","claim":"Menschen können erhebliche Planungskapazität aufbringen.","reason":"Sie nennt Ernährungsregeln und Fitnessziele als Gegenbeispiele zur Planungsunfähigkeit.","type":"Dialektischer Schluss · Induktion (verallgemeinernd)","id":"A125","family":"Dialektischer Schluss","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-02","page":1}],"implicitPremise":"Ein belegtes Beispiel erfolgreicher Planung widerlegt die Allaussage, Menschen könnten keine anspruchsvollen Pläne verfolgen.","assessment":"Die Beispiele zeigen Fähigkeit in manchen Bereichen, nicht Kapazität für alle Lebensbereiche zugleich.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus Fitnessplanung einzelner Menschen folgt keine universelle Verfügbarkeit umfassender Klimaplanung.","page":9}],"verification":"Lege fest, ob eine pauschale Unfähigkeit oder nur die Breite dauernder Planung bestritten wird.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Planung in einem wichtigen Bereich ist nicht auf alle Bereiche übertragbar.","reason":"Für Ernährung kann Aufmerksamkeit vorhanden sein, während andere Entscheidungen routiniert bleiben.","type":"Dialektischer Schluss","id":"A126","family":"Dialektischer Schluss","legacyType":"Geltungsbegrenzung","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine Fähigkeit unter hoher Motivation in einem Bereich gilt nicht ohne Weiteres in allen anderen Bereichen.","assessment":"Die Geltungsbegrenzung ist eine nachvollziehbare Antwort auf die Verallgemeinerung, benötigt aber keine Behauptung völliger Unfähigkeit.","fallacyChecks":[{"id":"VII-01","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Die Übertragung von einem motivierten Bereich auf alle Alltagsentscheidungen wird bestritten.","page":9}],"verification":"Untersuche verfügbare Zeit, Motivation und mögliche Entlastung durch Routinen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Gute Entscheidungen sollten möglichst einfach erreichbar sein.","reason":"Der aufwendige Vergleich von Ernährungs- und Umweltscores kann überfordern.","type":"Praktischer Schluss · Kausaler Schluss","id":"A127","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Eine Entscheidungsgestaltung soll erwünschte vertretbare Optionen ohne übermässigen Informationsaufwand erreichbar machen.","assessment":"Das praktische Ziel wird mit einer psychologischen Belastung begründet, nicht allein durch ein Modellwort.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Einfachheit allein ist keine hinreichende Bedingung für moralisch oder sachlich gute Entscheidungen.","page":6}],"verification":"Ergänze Kriterien für gute Defaults, Transparenz und freie Korrigierbarkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Ein persönlicher Plan muss keine komplexe tägliche Optimierung sein.","reason":"Wenige Regeln wie weniger Flüge oder Fleisch können die Entscheidung gerade vereinfachen.","type":"Dialektischer Schluss · Praktischer Schluss","id":"A128","family":"Dialektischer Schluss","legacyType":"Begriffspräzisierung","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-08","page":2}],"implicitPremise":"Wenige beständige Regeln können den Planungsaufwand gerade reduzieren.","assessment":"Bleisch präzisiert «Plan» anders als umfassende laufende Optimierung; damit verändert sich die Reichweite des Kapazitätseinwands.","fallacyChecks":[{"id":"VI-05","status":"diskutiert","label":"Diskutiertes Muster – nicht individuell diagnostiziert","reason":"Der Streit kann auf zwei Bedeutungen von Plan beruhen; nicht jeder Begriffsunterschied ist schon ein vollzogener Fehlschluss.","page":8}],"verification":"Definiere gemeinsam, wie viele Regeln, Ausnahmen und laufende Vergleiche gemeint sind.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Streiten beide über denselben Begriff von Plan?","Rekonstruiere eine Position, die beide Einwände berücksichtigt."],"teacher":"Bleisch widerlegt eher eine pauschale Unfähigkeit als begrenzte Gesamtkapazität. Knutti widerlegt eher umfassende Optimierung als jeden einfachen Vorsatz. Das teilweise Aneinandervorbeireden benennen.","start":2852.8,"id":"s43","end":2930.0,"duration":77.2,"openingCueStart":2852.8},{"title":"Gesellschaftlicher Plan und Entmündigungseinwand","theme":"Politik und Freiheit","arguments":[{"speaker":"Knutti","claim":"Politische Koordination kann individuellen Planungsaufwand reduzieren.","reason":"Ein gemeinsamer Heizungsstandard vereinfacht private Einzelentscheidungen.","type":"Praktischer Schluss · Kausaler Schluss","id":"A129","family":"Praktischer Schluss","legacyType":"Zweck-Mittel-Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-06","page":2}],"implicitPremise":"Gemeinsame Standards können wiederholte individuelle Optimierung reduzieren und sind unter Legitimitäts- und Nutzenbedingungen prüfenswert.","assessment":"Der Entlastungseffekt begründet einen möglichen Zweck, nicht automatisch die Rechtmässigkeit oder moralische Zulässigkeit des Standards.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus geringerer Denklast allein folgt ohne Freiheits- und Verhältnismässigkeitsnorm keine Regelungspflicht.","page":12}],"verification":"Vergleiche Unterstützung, Information, Anreize und verbindliche Standards.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Die Verlagerung von Entscheidungen auf den Staat kann Selbstbestimmung schwächen.","reason":"Menschen könnten die eigene Urteils- und Handlungsverantwortung abgeben.","type":"Prädiktiver Schluss · Praktischer Schluss","id":"A130","family":"Prädiktiver Schluss","legacyType":"Freiheitsargument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Politische Regeln sind auch nach ihrer Wirkung auf Selbstbestimmung und Verantwortung zu beurteilen.","assessment":"Der Freiheitseinwand ist relevant. Eine völlige Entmündigung folgt aber nicht allein aus einer koordinierten Entscheidung.","fallacyChecks":[{"id":"VIII-08","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Der Übergang von einer einzelnen Regel zu totaler Unselbstständigkeit wäre ohne Mechanismus eine schiefe Ebene.","page":12}],"verification":"Benenne konkrete verlorene Entscheidungen sowie verbleibende Wahl- und Mitgestaltungsrechte.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Gemeinsame Regeln schliessen individuelle Handlungspläne nicht vollständig aus.","reason":"Viele persönliche Möglichkeiten bleiben neben koordinierten Standards erhalten.","type":"Dialektischer Schluss","id":"A131","family":"Dialektischer Schluss","legacyType":"Differenzierungsargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Ein Teil gemeinsamer Regeln kann mit vielen privaten Wahlmöglichkeiten zugleich bestehen.","assessment":"Der Schluss bestreitet eine ausschliessende Gegenüberstellung von Koordination und persönlicher Planung.","fallacyChecks":[{"id":"VI-03","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Staatliche Koordination und jede individuelle Freiheit werden nicht als unvereinbare Gesamtalternativen behandelt.","page":8}],"verification":"Zeige, welche Möglichkeiten erhalten bleiben und welche Einschränkungen begründet werden müssen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Freiheit wird eingeschränkt, welche Handlungsmöglichkeit möglicherweise eröffnet?","Unter welchen Bedingungen wäre die Koordination verhältnismässig?"],"teacher":"Aus Entlastung folgt nicht automatisch Legitimität. Aus einer einzelnen Regel folgt aber ebenso wenig totale Entmündigung. Reichweite, Verfahren und Alternativen sind zu prüfen.","start":2930.0,"id":"s44","end":2986.52,"duration":56.52,"openingCueStart":2930.0},{"title":"LED-Lampen, demokratische Mitgestaltung und Ausschlüsse","theme":"Politik und Freiheit","arguments":[{"speaker":"Knutti","claim":"Standards können Umstellungen ohne individuelle Detailplanung ermöglichen.","reason":"Der Wechsel von Glühlampen zu LED dient als Beispiel veränderter Auswahlbedingungen.","type":"Analogieschluss · Praktischer Schluss","id":"A132","family":"Analogieschluss","legacyType":"Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-08","page":2}],"implicitPremise":"Ein veränderter Produktstandard kann einen technischen Umstieg ermöglichen, ohne dass jede Person ihn selbst vollständig planen muss.","assessment":"LED dient als Beispiel für veränderte Entscheidungsarchitektur. Der Schluss ist nicht auf jede Konsumentscheidung übertragbar.","fallacyChecks":[{"id":"VIII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Reichweite, Kosten und Eingriffstiefe eines Lampenstandards unterscheiden sich von anderen Politiken.","page":12}],"verification":"Vergleiche konkrete Standardisierungsfälle mit ihren Alternativen und Belastungen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Ein gemeinsamer Plan muss nicht fremdbestimmt sein.","reason":"Wahlen und Abstimmungen ermöglichen Mitgestaltung der Regeln.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A133","family":"Praktischer Schluss","legacyType":"Legitimationsargument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Wenn Betroffene demokratisch Einfluss nehmen können, kann ein gemeinsamer Plan ein Element kollektiver Selbstbestimmung sein.","assessment":"Der Schluss entkräftet zwingende Fremdbestimmung, nicht alle materiellen Freiheits- oder Minderheitseinwände.","fallacyChecks":[{"id":"IX-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Mehrheitszustimmung allein macht eine Regel noch nicht moralisch richtig.","page":13}],"verification":"Prüfe Beteiligung, Grundrechte, Minderheitenschutz und Verhältnismässigkeit zusätzlich.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"In der direkten Demokratie sind Bürger auch Mitgestalter staatlicher Entscheidungen.","reason":"Sie präzisiert den Staat als politisches Gemeinwesen.","type":"Dialektischer Schluss · Praktischer Schluss","id":"A134","family":"Dialektischer Schluss","legacyType":"Demokratisches Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2},{"id":"I-08","page":2}],"implicitPremise":"Der Staat ist im demokratischen Zusammenhang auch ein durch Bürger mitgestaltetes institutionelles Gefüge.","assessment":"Die Präzisierung korrigiert das Bild eines völlig fremden Einzelakteurs, darf aber unterschiedliche politische Macht nicht verdecken.","fallacyChecks":[{"id":"VI-11","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Der Staat wird gerade nicht als von Menschen unabhängiges handelndes Ding behandelt.","page":9}],"verification":"Unterscheide institutionelle Mitwirkung, tatsächlichen Einfluss und individuelle Zustimmung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Die Mitbestimmungsbehauptung hat eine wichtige Grenze.","reason":"Viele Bewohner ohne Schweizer Pass dürfen nicht mitbestimmen.","type":"Dialektischer Schluss","id":"A135","family":"Dialektischer Schluss","legacyType":"Einschränkungsargument","legacyFamily":"Begriffs- / Prämissenprüfung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine Behauptung allgemeiner Mitbestimmung muss auf die tatsächlich Stimmberechtigten eingeschränkt werden.","assessment":"Der Hinweis auf Bewohner ohne Stimmrecht begrenzt die Domäne der Allaussage, ohne Demokratie insgesamt zu bestreiten.","fallacyChecks":[{"id":"VI-09","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Ein Recht bestimmter Mitglieder darf nicht jedem betroffenen Mitglied des Gemeinwesens zugeschrieben werden.","page":8}],"verification":"Benenne, wer entscheiden darf, wer betroffen ist und welche anderen Beteiligungsrechte bestehen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Widerlegt demokratische Zustimmung jeden Freiheits- oder Minderheiteneinwand?","Welche Personen sind vom Plan betroffen, ohne gleichberechtigt mitzuentscheiden?"],"teacher":"Demokratische Beteiligung begründet ein Legitimationsverfahren, nicht automatisch jede einzelne Massnahme. Der LED-Vergleich illustriert Standardisierung, beweist aber nicht deren Übertragbarkeit auf jede Lebensentscheidung.","start":2986.52,"id":"s45","end":3039.16,"duration":52.64,"openingCueStart":2986.52},{"title":"NIMBY und frühere Infrastrukturprojekte","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Bleisch","claim":"Gesellschaftliche Zustimmung zu grossen Projekten erscheint heute schwieriger.","reason":"Sie vergleicht aktuelle Windprojekte mit früheren Kraftwerken, Tunneln, Bahnprojekten und Umsiedlungen.","type":"Induktion (verallgemeinernd) · Analogieschluss","id":"A136","family":"Induktion (verallgemeinernd)","legacyType":"Historischer Vergleich","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-04","page":2}],"implicitPremise":"Beobachtete Unterschiede zwischen früheren und heutigen Infrastrukturkonflikten können auf veränderte Akzeptanzbedingungen hinweisen.","assessment":"Der historische Vergleich ist eine induktive Ausgangshypothese, kein Nachweis einer einheitlich willigeren Vergangenheit.","fallacyChecks":[{"id":"VII-03","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Eine Auswahl erfolgreicher früherer Grossprojekte kann damaligen Widerstand und gescheiterte Projekte ausblenden.","page":9}],"verification":"Vergleiche systematisch Konflikte, Betroffenenrechte und nicht verwirklichte Vorhaben beider Perioden.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Langfristiges gemeinsames Investieren kann sich über Generationen lohnen.","reason":"Frühere Infrastruktur und die Bahnelektrifizierung dienen als Erfolgsbeispiele.","type":"Induktion (verallgemeinernd) · Prädiktiver Schluss · Praktischer Schluss","id":"A137","family":"Induktion (verallgemeinernd)","legacyType":"Folgen- und Beispielargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-07","page":2},{"id":"I-08","page":2}],"implicitPremise":"Langfristig erfolgreiche Infrastrukturbeispiele können die Möglichkeit generationenübergreifenden Nutzens zeigen.","assessment":"Die Beispiele stützen Möglichkeit und eine prüfbare Erwartung; sie garantieren weder gleichen Erfolg noch faire Belastung neuer Projekte.","fallacyChecks":[{"id":"VII-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Nur die rückblickend erfolgreichen Projekte zu betrachten könnte Survivorship Bias erzeugen.","page":10}],"verification":"Ergänze Misserfolge, Alternativkosten und die Verteilung von Nutzen und Umsiedlungslasten.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Wird die Vergangenheit hier ausgewogen oder selektiv erinnert?","Was müssten die Erfolgsgeschichten über Kosten, Betroffene und Widerstand zeigen?"],"teacher":"Aus früherem Nutzen folgt nicht, dass frühere Umsiedlungen gerecht waren oder heutige Einwände unbegründet sind. Die behauptete geringere damalige NIMBY-Haltung braucht historisches Material.","start":3039.16,"id":"s46","end":3115.36,"duration":76.2,"openingCueStart":3039.16},{"title":"Individualisierung, Polarisierung und mediale Blasen","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Knutti","claim":"Individualisierung kann gemeinsame Infrastrukturentscheidungen erschweren.","reason":"Eigener Nutzen erhält mehr Gewicht als der gesellschaftliche Gesamtvorteil.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A138","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausale Hypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Eine stärkere Gewichtung des privaten Nutzens kann gemeinsame Entscheidungen unter bestimmten Bedingungen erschweren.","assessment":"Individualisierung ist eine Ursachenhypothese, keine Diagnose der Motive aller Einsprechenden.","fallacyChecks":[{"id":"X-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Sachlichen Widerstand ohne Prüfung der Situation als persönlichen Egoismus zu erklären wäre ein Attributionsfehler.","page":14}],"verification":"Prüfe konkrete Interessen, Verfahrensprobleme und sachliche Einwände.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Polarisierung kann überparteiliche Lösungen blockieren.","reason":"Er beschreibt verengte politische Lager und wenig Raum dazwischen.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A139","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausale Hypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Starke Lagerbindung kann Kompromissbildung und parteiübergreifende Lösungen erschweren.","assessment":"Die Erklärung ist abduktiv und aufhebbar; die vereinfachte Lagerdarstellung muss empirisch eingegrenzt werden.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Polarisierung darf nicht als ausschliessliche Ursache sämtlicher Blockaden behandelt werden.","page":11}],"verification":"Miss Lagerbindung, tatsächliche Koalitionen und weitere Entscheidungsbedingungen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Mediale Blasen und Falschinformationen können Widerstand verstärken.","reason":"Schnell verbreitete Geschichten bündeln Aufmerksamkeit in Gruppen.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A140","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausale Hypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Selektiv verbreitete oder falsche Informationen können Wahrnehmung und Organisation von Widerstand beeinflussen.","assessment":"Ein möglicher Mechanismus wird genannt. Die Zugehörigkeit zu einer Gruppe belegt keine falsche Überzeugung ihrer Mitglieder.","fallacyChecks":[{"id":"VII-04","status":"diskutiert","label":"Diskutiertes Muster – nicht individuell diagnostiziert","reason":"Bestätigungsfehler ist als möglicher Mechanismus relevant, im Einzelfall aber nicht aus der Ferne diagnostiziert.","page":10}],"verification":"Untersuche konkrete Inhalte, Verbreitung und Wirkungen statt jede Opposition als Blase zu bezeichnen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Wohlstand und Müdigkeit könnten Zukunftsinvestitionen schwächen.","reason":"Er kontrastiert heutige Sättigung mit früherer Aufbruchsstimmung.","type":"Abduktion (Schluss auf die beste Erklärung)","id":"A141","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Psychologische Hypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1}],"implicitPremise":"Wohlstand und Sättigung könnten die Motivation für neue Gemeinschaftsprojekte reduzieren.","assessment":"Die vorsichtige Erklärung enthält eine psychologische Vermutung; die Charakterisierung einer Gesellschaft als müde ist kein eigenständiger Beleg.","fallacyChecks":[{"id":"X-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Situative Hürden könnten durch eine pauschale Charakterdiagnose ersetzt werden.","page":14}],"verification":"Vergleiche alternative Ursachen wie Komplexität, Zeitknappheit und vorhandene Projektkonflikte.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche der vier Erklärungen sind belegt und welche nur plausibel behauptet?","Wie könnte man ihre jeweilige Erklärungskraft empirisch unterscheiden?"],"teacher":"Knutti formuliert teils vorsichtig. Eine Diagnose von Egoismus darf nicht jedes sachliche Projektgegenargument delegitimieren. Ursachenbündel sind nicht schon durch Aufzählung nachgewiesen.","start":3115.36,"id":"s47","end":3163.96,"duration":48.6,"openingCueStart":3115.36},{"title":"Gute Vorfahren: Gerechtigkeit und Sinn","theme":"Gerechtigkeit","arguments":[{"speaker":"Bleisch","claim":"Entscheidungen sollten auch aus der Perspektive künftiger Generationen getroffen werden.","reason":"Vermächtnisdenken fragt nach den hinterlassenen Lebensbedingungen.","type":"Praktischer Schluss","id":"A142","family":"Praktischer Schluss","legacyType":"Normatives Argument","legacyFamily":"Norm / Wert","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Die Interessen künftiger Menschen sollen in gegenwärtigen Entscheidungen mitberücksichtigt werden.","assessment":"Vermächtnisdenken ist ein normativer praktischer Rahmen, kein aus der Existenz der Zukunft allein deduzierter Pflichtenkatalog.","fallacyChecks":[{"id":"IX-01","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Schutz- und Gerechtigkeitsnorm ist der eigentliche zusätzliche Grund; sie ist offenzulegen und zu begründen.","page":12}],"verification":"Erkläre den moralischen Status künftiger Interessen und Grenzen gegenwärtiger Zumutbarkeit.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Langfristiges gemeinsames Gestalten kann auch der Gegenwart Sinn geben.","reason":"Aufgaben jenseits des eigenen Lebens werden als sinnstiftend beschrieben.","type":"Induktion (verallgemeinernd) · Kausaler Schluss","id":"A143","family":"Induktion (verallgemeinernd)","legacyType":"Nutzenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-06","page":2}],"implicitPremise":"Aufgaben über das eigene Leben hinaus können unter passenden Bedingungen als sinnstiftend erlebt werden.","assessment":"Der empirisch-psychologische Anspruch ist nicht schon durch einen philosophischen Buchverweis belegt.","fallacyChecks":[{"id":"V-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Philosophische Autorität ersetzt keine empirische Evidenz für Häufigkeit und Wirkung des Sinnerlebens.","page":6}],"verification":"Trenne philosophische Plausibilität, persönliche Erfahrung und psychologische Untersuchungen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Ein solches Denken verbindet moralischen Anspruch und persönliche Motivation.","reason":"Generativität kann zugleich anderen nutzen und das eigene Leben orientieren.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A144","family":"Praktischer Schluss","legacyType":"Verknüpfungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine Handlung kann zugleich durch Pflichten und durch persönlichen Sinn motiviert sein.","assessment":"Das Zusammenführen zweier Gründe ist dialektisch möglich; keiner der beiden Gründe beweist automatisch den anderen.","fallacyChecks":[{"id":"IX-02","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Verbindung wäre erst problematisch, wenn moralisch gut einfach mit sinnstiftend oder lustvoll gleichgesetzt würde.","page":12}],"verification":"Halte moralische Rechtfertigung und subjektiven Motivationsgewinn getrennt sichtbar.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Sind moralische Pflicht und Sinngewinn dieselbe Begründung?","Welche zusätzliche Annahme braucht die Behauptung, viele Menschen empfänden das als sinnstiftend?"],"teacher":"Krznarics Buch liefert einen philosophischen Bezugsrahmen. Der Verweis allein ist kein empirischer Nachweis allgemeiner Motivation.","start":3163.96,"id":"s48","end":3225.92,"duration":61.96,"openingCueStart":3163.96},{"title":"Nachhaltigkeit gegen kurze Anreizzyklen","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Knutti","claim":"Generationengerechtigkeit gehört bereits zum anerkannten Nachhaltigkeitsprinzip.","reason":"Er verweist auf die Schweizer Bundesverfassung.","type":"Praktischer Schluss · Dialektischer Schluss","id":"A145","family":"Praktischer Schluss","legacyType":"Norm- und Autoritätsargument","legacyFamily":"Autorität / Quellenbezug","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Ein anerkanntes institutionelles Nachhaltigkeitsprinzip liefert einen relevanten Normbezug für generationenübergreifende Entscheidungen.","assessment":"Der Verfassungsverweis begründet eine institutionelle Orientierung, nicht ohne Weiteres die moralische oder rechtliche Richtigkeit jeder Massnahme.","fallacyChecks":[{"id":"V-07","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Eine einschlägige Normquelle ist kein unzulässiger Autoritätsersatz, solange ihr Geltungsbereich begrenzt bleibt.","page":6}],"verification":"Prüfe Wortlaut und Reichweite des Prinzips sowie seine Abwägung mit anderen Normen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Menschen sind durchaus zu langfristiger Verantwortung fähig.","reason":"Die Finanzierung der Ausbildung eigener Kinder dient als Gegenbeispiel zu reinem Kurzfristdenken.","type":"Induktion (verallgemeinernd) · Dialektischer Schluss","id":"A146","family":"Induktion (verallgemeinernd)","legacyType":"Gegenbeispiel","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-14","page":2}],"implicitPremise":"Ein belegter Fall langfristiger Fürsorge zeigt, dass Menschen grundsätzlich über die unmittelbare Gegenwart hinaus planen können.","assessment":"Das Gegenbeispiel widerlegt eine pauschale Unfähigkeit; es belegt keine automatische Verantwortung für alle unbekannten Nachkommen.","fallacyChecks":[{"id":"VII-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Von Fürsorge für eigene Kinder auf gleiches Handeln gegenüber allen künftigen Menschen zu schliessen wäre zu stark.","page":9}],"verification":"Vergleiche Nähe, Motivation und institutionelle Unterstützung der jeweiligen Verantwortung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Institutionelle Anreize können langfristiges Handeln dennoch schwächen.","reason":"Quartalslogik der Wirtschaft und Wahlzyklen belohnen kurzfristige Ergebnisse.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A147","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Institutionelles Kausalargument","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Kurzfristige Anreiz- und Belohnungszyklen können längerfristige Investitionen benachteiligen.","assessment":"Das institutionelle Modell bietet einen Mechanismus, benötigt aber Unterschiede nach Branchen und politischen Verfahren.","fallacyChecks":[{"id":"VIII-06","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Quartale und Wahlperioden sind nicht die einzigen Ursachen kurzer Planungshorizonte.","page":11}],"verification":"Prüfe reale Investitionsdauern, langfristige Verträge und Gegenbeispiele vorausschauender Institutionen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Lücke besteht zwischen anerkanntem Prinzip und tatsächlichen Anreizen?","Was unterscheidet Fürsorge für eigene Kinder von Verantwortung für unbekannte spätere Menschen?"],"teacher":"Ein Verfassungsverweis bestätigt nicht automatisch eine konkrete Politik. Knuttis Generalisierungen über Investitionshorizonte müssen nach Branchen und Institutionen differenziert werden.","start":3225.92,"id":"s49","end":3291.16,"duration":65.24,"openingCueStart":3225.92},{"title":"Windräder vor der Haustür: individuelle Belastung","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Bleisch","claim":"Gesamtgesellschaftlicher Nutzen kann mit örtlichen Individualkosten kollidieren.","reason":"Sehr grosse geplante Windanlagen betreffen konkrete Wohn- und Landschaftssituationen.","type":"Praktischer Schluss","id":"A148","family":"Praktischer Schluss","legacyType":"Verteilungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Ein Gesamtvorteil rechtfertigt nicht ohne weitere Fairnessprüfung jede örtliche Last.","assessment":"Der Verteilungseinwand ist für einen praktischen Schluss relevant, unabhängig davon, ob das Gesamtziel geteilt wird.","fallacyChecks":[{"id":"VI-09","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Ein positiver Gesamtsaldo darf nicht als Vorteil jeder betroffenen Person ausgegeben werden.","page":8}],"verification":"Erfasse lokale Belastung, Ausgleich, Beteiligung und räumliche Alternativen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Eine abstrakte Zustimmung sollte am eigenen Betroffensein geprüft werden.","reason":"Die Frage nach einer Anlage beim eigenen Haus prüft die Konsistenz der Position.","type":"Kontrafaktisches Schliessen · Praktischer Schluss · Dialektischer Schluss","id":"A149","family":"Kontrafaktisches Schliessen","legacyType":"Perspektivwechsel","legacyFamily":"Analogie / Vergleich","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-11","page":2},{"id":"I-08","page":2},{"id":"I-14","page":2}],"implicitPremise":"Eine konsistente Empfehlung sollte unter vergleichbaren Bedingungen auch aus der Perspektive der selbst Betroffenen vertretbar sein.","assessment":"Der Perspektivwechsel testet zumutbare Regeln, ist aber kein Ersatz für Sachprüfung und keine Widerlegung aufgrund persönlicher Vorlieben.","fallacyChecks":[{"id":"V-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Persönliche Ablehnung würde das Sachargument nicht automatisch falsch machen.","page":6}],"verification":"Formuliere die Regel unabhängig von Personen und prüfe sie anhand vergleichbarer Belastung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die zugespitzte Nähevorstellung darf nicht ungeprüft übernommen werden.","reason":"Er verweist auf vorgesehene Abstände.","type":"Dialektischer Schluss","id":"A150","family":"Dialektischer Schluss","legacyType":"Prämissenkritik","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine Einzelfallbewertung darf nicht von einer übertriebenen tatsächlichen Nähe ausgehen.","assessment":"Die Prämissenkritik ist relevant, sofern die Abstände tatsächlich die strittige Vorstellung korrigieren.","fallacyChecks":[{"id":"VI-02","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"Eine voraussetzungsreiche Frage nach der Turbine direkt vor dem Haus wird auf ihre Tatsachenannahme geprüft.","page":8}],"verification":"Nenne reale Abstände und Belastungsdaten; Abstand allein erledigt nicht jede Landschaftsfrage.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Ist die Frage nach dem eigenen Haus ein legitimer Konsistenztest oder ein Ersatz für Sachprüfung?","Welche Belastungen lassen sich messen, welche betreffen Wertungen?"],"teacher":"Die Szene enthält noch keine belegten Abstands- oder Belastungswerte. NIMBY darf berechtigte lokale Interessen nicht automatisch abwerten.","start":3291.16,"id":"s50","end":3330.12,"duration":38.96,"openingCueStart":3291.16},{"title":"Wind, Staumauern und Autobahnen: gleiche Massstäbe?","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Knutti","claim":"Die Ablehnung einer Technik hängt auch von erlernter Wahrnehmung ab.","reason":"Er kontrastiert persönliche Faszination für Windräder mit verbreiteter Abneigung.","type":"Abduktion (Schluss auf die beste Erklärung) · Induktion (verallgemeinernd)","id":"A151","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Perspektivenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-02","page":1}],"implicitPremise":"Erfahrung, Gewöhnung und ästhetische Präferenzen können Akzeptanz von Technik mitprägen.","assessment":"Die eigene positive Wahrnehmung illustriert Unterschiedlichkeit, beweist aber nicht die Harmlosigkeit der Anlage.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Persönliche Faszination dürfte objektive Belastungsprüfung nicht ersetzen.","page":9}],"verification":"Trenne ästhetische Bewertung, gemessene Belastung und gesellschaftliche Akzeptanzdaten.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Landschaftseingriffe werden nicht immer mit gleichen Massstäben beurteilt.","reason":"Staumauern und Autobahnen finden trotz erheblicher Eingriffe hohe Akzeptanz.","type":"Analogieschluss · Dialektischer Schluss","id":"A152","family":"Analogieschluss","legacyType":"Konsistenz- und Vergleichsargument","legacyFamily":"Konsistenzargument","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-04","page":2},{"id":"I-14","page":2}],"implicitPremise":"Bei relevant vergleichbaren Eingriffen sollten gleiche Bewertungsmassstäbe gelten, sofern keine sachlichen Unterschiede vorliegen.","assessment":"Der Konsistenzvergleich kann selektive Standards offenlegen. Er rechtfertigt keinen zusätzlichen Eingriff allein durch frühere Schäden.","fallacyChecks":[{"id":"VI-16","status":"diskutiert","label":"Diskutiertes Muster – nicht individuell diagnostiziert","reason":"Doppelte Standards wären nur bei sachlich vergleichbaren Fällen ohne relevanten Differenzgrund gegeben.","page":9},{"id":"IX-05","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"«Wir haben früher eingegriffen, also dürfen wir wieder eingreifen» wäre keine ausreichende Rechtfertigung.","page":13}],"verification":"Vergleiche Nutzen, Belastung, Alternativen und kumulative Landschaftseffekte.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Energieversorgung braucht einen Ort in der genutzten Landschaft.","reason":"Infrastruktur ist Teil menschlicher Raumnutzung, nicht ausserhalb davon verfügbar.","type":"Deduktion · Praktischer Schluss","id":"A153","family":"Deduktion","legacyType":"Notwendigkeitsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-01","page":1},{"id":"I-08","page":2}],"implicitPremise":"Wenn Energieversorgung bestimmte physische Anlagen benötigt, muss für eine gewollte Versorgung geeigneter Raum unter Abwägungsnormen bereitstehen.","assessment":"Die Existenz benötigter Infrastruktur ist konzeptionell nachvollziehbar. Ein bestimmter Standort folgt daraus noch nicht.","fallacyChecks":[{"id":"IV-16","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Notwendigkeit irgendeiner Infrastruktur ist keine hinreichende Begründung jedes konkreten Projekts.","page":6}],"verification":"Begründe Bedarf, Technologie, Standort und verhältnismässige Alternativen separat.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Sind die Eingriffe relevant vergleichbar oder unterscheiden sie sich in entscheidenden Punkten?","Folgt aus akzeptierten früheren Eingriffen die Zulässigkeit neuer Eingriffe?"],"teacher":"Der Vergleich kann selektive Massstäbe aufdecken. Er wäre ein Fehlschluss, wenn frühere Belastung allein als Rechtfertigung zusätzlicher Belastung diente. Ästhetische Vorlieben sind keine objektiven Unbedenklichkeitsbelege.","start":3330.12,"id":"s51","end":3377.64,"duration":47.52,"openingCueStart":3330.12},{"title":"Techniksättigung als Gegenerklärung","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Bleisch","claim":"Akzeptanz von Technik kann sich historisch verändern.","reason":"Frühere Begeisterung fürs Autobahnschauen kontrastiert mit heutiger Wahrnehmung.","type":"Induktion (verallgemeinernd)","id":"A154","family":"Induktion (verallgemeinernd)","legacyType":"Historisches Beispiel","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1}],"implicitPremise":"Ein historisches Erlebnis kann einen möglichen Wandel technischer Wahrnehmung illustrieren.","assessment":"Die Autobahn-Anekdote zeigt eine Möglichkeit der Bewertungsgeschichte, keine repräsentative Kurve der Gesamtbevölkerung.","fallacyChecks":[{"id":"VII-02","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Persönliche Erinnerung wäre als alleiniger Beweis einer allgemeinen Akzeptanzentwicklung zu schwach.","page":9}],"verification":"Ergänze zeitgenössische Befragungen, Konfliktberichte und unterschiedliche Bevölkerungsgruppen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Natursehnsucht kann auf bereits hohe Verbauung reagieren.","reason":"Nicht nur Rückständigkeit, sondern Belastungssättigung könnte neue Ablehnung erklären.","type":"Abduktion (Schluss auf die beste Erklärung) · Kausaler Schluss","id":"A155","family":"Abduktion (Schluss auf die beste Erklärung)","legacyType":"Kausale Gegenhypothese","legacyFamily":"Ursache / Wirkung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-03","page":1},{"id":"I-06","page":2}],"implicitPremise":"Bereits bestehende kumulative Belastung kann zusätzlichen Widerstand besser erklären als blosse Zukunftsscheu.","assessment":"Die Gegenhypothese erweitert den Ursachenraum; weder sie noch Knuttis Erklärung ist allein durch Plausibilität entschieden.","fallacyChecks":[{"id":"VIII-05","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die mögliche Drittbedingung bereits hoher Verbauung wird ausdrücklich berücksichtigt.","page":11}],"verification":"Prüfe bestehende Belastung, neue Eingriffsintensität und die Gründe tatsächlich Betroffener.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche alternative Erklärung ergänzt Bleisch zu Knuttis Diagnose?","Welche Beobachtungen würden Gewöhnung und Sättigung voneinander unterscheiden?"],"teacher":"Eine abweichende Bewertung kann rational begründete Präferenzänderung sein. Die Anekdote ist eine Illustration, keine repräsentative Zeitreihe.","start":3377.64,"id":"s52","end":3412.8,"duration":35.16,"openingCueStart":3377.64},{"title":"Heidiland, Kulturlandschaft und Energiebedarf","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Knutti","claim":"Das verbreitete Alpenbild blendet Nutzung und Wirtschaft aus.","reason":"Er verweist auf eine Studie und die starke Gewichtung von Natur gegenüber Wirtschaft.","type":"Induktion (verallgemeinernd) · Abduktion (Schluss auf die beste Erklärung)","id":"A156","family":"Induktion (verallgemeinernd)","legacyType":"Studien- und Wahrnehmungsargument","legacyFamily":"Autorität / Quellenbezug","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-03","page":1}],"implicitPremise":"Eine passend konzipierte Befragung kann zeigen, welche Vorstellungen Befragte bevorzugen und was sie wenig nennen.","assessment":"Die Studienberufung kann Wahrnehmungsaspekte stützen; ohne Methodik sind Repräsentativität und Interpretation offen.","fallacyChecks":[{"id":"VII-07","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus einer nicht passenden Stichprobe liesse sich nicht auf alle Schweizer Alpenvorstellungen schliessen.","page":10}],"verification":"Prüfe Stichprobe, Frageform, Auftrag, Kategorien und den Unterschied zwischen Nennung und Bedeutung.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Die Alpen sind keine vollständig unberührte Natur.","reason":"Abholzung, Landwirtschaft und Tourismus haben sie seit Jahrhunderten mitgeprägt.","type":"Induktion (verallgemeinernd) · Dialektischer Schluss","id":"A157","family":"Induktion (verallgemeinernd)","legacyType":"Historisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-14","page":2}],"implicitPremise":"Historisch belegte Eingriffe widersprechen der Behauptung, die heutige Alpenlandschaft sei vollständig unberührte Natur.","assessment":"Als Gegenbeispiel gegen völlige Unberührtheit ist der Schluss begrenzt tragfähig. Er entscheidet keine künftige Nutzungsnorm.","fallacyChecks":[{"id":"V-17","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Die Beschreibung einer Kulturlandschaft ist weder schon ein Naturappell noch eine pauschale Abwertung des Natürlichen.","page":7}],"verification":"Belege Veränderungen und trenne ihre Beschreibung vom heutigen Schutzwert.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Energie- und Lebensbedürfnisse erfordern Nutzungskompromisse.","reason":"Versorgung und lokale Lebensgrundlagen benötigen gewisse Infrastruktur.","type":"Praktischer Schluss","id":"A158","family":"Praktischer Schluss","legacyType":"Abwägungsargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2}],"implicitPremise":"Wenn Versorgung und lokale Lebensgrundlagen legitime Ziele sind, sind geeignete Nutzungskompromisse unter Schutz- und Zumutbarkeitsnormen zu prüfen.","assessment":"Das praktische Abwägungsargument enthält mehrere Ziele, aber keine automatische Vorrangregel zugunsten neuer Infrastruktur.","fallacyChecks":[{"id":"IX-01","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus bestehender Nutzung oder wirtschaftlichem Bedarf folgt ohne Abwägungsnorm keine konkrete Erlaubnis.","page":12}],"verification":"Vergleiche Schutzgüter, Lebensgrundlagen, Effizienz und alternative Standorte.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Widerlegt Kulturlandschaft den Anspruch auf weiteren Landschaftsschutz?","Welche konkret erforderliche Infrastruktur folgt aus dem allgemeinen Energiebedarf — und welche nicht?"],"teacher":"Aus «schon genutzt» folgt nicht «beliebig weiter nutzbar». Die genannte BKW-Studie braucht Angaben zu Fragestellung, Stichprobe und Auftraggeberinteresse.","start":3412.8,"id":"s53","end":3478.56,"duration":65.76,"openingCueStart":3412.8},{"title":"Traditionsargument und Zukunftsgestaltung","theme":"Zukunft und Landschaft","arguments":[{"speaker":"Knutti","claim":"Überlieferte Gewohnheit allein ist kein ausreichender Grund gegen Veränderung.","reason":"Die Berufung auf das bisher Übliche prüft die künftigen Bedingungen nicht.","type":"Dialektischer Schluss","id":"A159","family":"Dialektischer Schluss","legacyType":"Traditionskritik","legacyFamily":"Gegenbeispiel / Widerlegung","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-14","page":2}],"implicitPremise":"Eine Entscheidung braucht relevante Gründe für heutige und künftige Bedingungen; lange Übung allein ist dafür nicht hinreichend.","assessment":"Knutti kritisiert eine Traditionsbegründung. Ihm wird nicht die im Zitat vorgeführte fehlerhafte Schlussform selbst zugeschrieben.","fallacyChecks":[{"id":"V-09","status":"zurueckgewiesen","label":"Im Argument zurückgewiesenes Fehlermuster","reason":"«Immer schon so gemacht» reicht als alleinige Rechtfertigung nicht aus.","page":7}],"verification":"Unterscheide blosse Gewohnheit von überprüfbarem Erfahrungswissen über bewährte Verfahren.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Eine sich wandelnde Welt verlangt aktive Anpassung und Gestaltung.","reason":"Technik und Geopolitik verändern sich unabhängig von lokalen Gewohnheiten.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A160","family":"Praktischer Schluss","legacyType":"Pragmatisches Argument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Bei veränderten Rahmenbedingungen sollen Strategien auf ihre künftige Eignung geprüft und gegebenenfalls angepasst werden.","assessment":"Ein praktischer Anpassungsschluss folgt unter einer Zielnorm, nicht aus Neuheit als eigenständigem Wert.","fallacyChecks":[{"id":"V-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Aus der Veränderung der Welt folgt nicht, dass jede neue Lösung besser ist.","page":7}],"verification":"Vergleiche Wirkungen alter und neuer Optionen statt Veränderung an sich zu rechtfertigen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Knutti","claim":"Regionale Erfahrung illustriert für ihn eine verbreitete Veränderungsskepsis.","reason":"Er nennt Herkunft, persönliche Kontakte und Abstimmungsmuster.","type":"Induktion (verallgemeinernd) · Abduktion (Schluss auf die beste Erklärung)","id":"A161","family":"Induktion (verallgemeinernd)","legacyType":"Erfahrungsargument","legacyFamily":"Fakten / Beispiele","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-02","page":1},{"id":"I-03","page":1}],"implicitPremise":"Persönliche Kontakte und regionale Muster können eine Hypothese über verbreitete Haltung anregen.","assessment":"Die Hinweise sind selektiv und tragen keine pauschale Charakterdiagnose jedes Menschen einer Region.","fallacyChecks":[{"id":"VII-11","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Von regionalen Abstimmungsergebnissen darf nicht auf Haltung und Motive jedes einzelnen Bewohners geschlossen werden.","page":10},{"id":"X-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Regionale Politik kann situative Ursachen haben statt eines einheitlichen rückwärtsgewandten Charakters.","page":14}],"verification":"Prüfe repräsentative individuelle Daten und differenziere Sachfragen sowie lokale Bedingungen.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Wann ist ein Traditionsbezug ein Fehlschluss und wann kann er Erfahrungswissen enthalten?","Welche Gefahr liegt darin, regionale Gruppen pauschal als rückwärtsgewandt darzustellen?"],"teacher":"Der Vergleich mit einem Bible Belt ist rhetorisch und kann stereotypisieren. Die Aussage zur Veränderung der Welt rechtfertigt nicht automatisch jede vorgeschlagene Neuerung.","start":3478.56,"id":"s54","end":3558.84,"duration":80.28,"openingCueStart":3478.56},{"title":"Schlussbilanz: Handeln, Kosten und Chancen","theme":"Kosten und Technik","arguments":[{"speaker":"Bleisch","claim":"Klimaschutz soll als Kostenabwägung statt nur als Ausgabe verstanden werden.","reason":"Sie fasst zusammen, dass Nichthandeln noch höhere Kosten verursache.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A162","family":"Praktischer Schluss","legacyType":"Zusammenfassendes Kostenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn vermiedene Schäden und Abhängigkeiten die vertretbaren Massnahmenkosten übersteigen, spricht das für Handeln.","assessment":"Die Schlussbilanz übernimmt eine im Gespräch begründete, aber empirisch nicht vollständig abgesicherte Kostenprognose.","fallacyChecks":[{"id":"VI-18","status":"abgrenzung","label":"Abgrenzung – kein Fehlschluss nachgewiesen","reason":"Eine Zusammenfassung begründeter Argumente ist kein eigenständiger Wahrheitsbeweis durch Wiederholung.","page":9}],"verification":"Verweise auf die strittigen Eingangsannahmen statt die Schlussformel als zusätzliche Evidenz zu zählen.","formalRule":null,"role":"Argument der sprechenden Person"}},{"speaker":"Bleisch","claim":"Die Transformation eröffnet auch Gestaltungschancen.","reason":"Sie bündelt den Gesprächsfaden von Veränderung, Innovation und Zukunft.","type":"Praktischer Schluss · Prädiktiver Schluss","id":"A163","family":"Praktischer Schluss","legacyType":"Zusammenfassendes Nutzenargument","legacyFamily":"Folgen / Nutzen / Zweck-Mittel","analysis":{"frameworkVersion":"handbuch-2026-10","forms":[{"id":"I-08","page":2},{"id":"I-07","page":2}],"implicitPremise":"Wenn eine Transformation reale Verbesserungsmöglichkeiten eröffnet, soll ihre Nutzung unter fairen und überprüfbaren Bedingungen erwogen werden.","assessment":"Die Zusammenfassung benennt eine Chance, keine garantierte Wirkung jeder Neuerung und keinen neuen unabhängigen Beleg.","fallacyChecks":[{"id":"V-10","status":"risiko","label":"Bedingtes Risiko – kein bestätigter Fehlschluss","reason":"Die Chance darf nicht in einen pauschalen Vorrang alles Neuen umgedeutet werden.","page":7}],"verification":"Formuliere konkrete Verbesserungsziele, Unsicherheiten und Bedingungen der Zustimmung.","formalRule":null,"role":"Argument der sprechenden Person"}}],"questions":["Welche Prämissen des Gesprächs müsste diese Schlussbilanz noch absichern?","Wähle das stärkste Gegenargument, das im Schluss nicht ausdrücklich beantwortet wird."],"teacher":"Dies ist eine Gesprächszusammenfassung, kein neuer unabhängiger Beleg. Abmoderation und Programmhinweise nach dem Gespräch enthalten keine zusätzlichen Argumente zur Klimakrise.","start":3558.84,"id":"s55","end":3578.4,"duration":19.56,"openingCueStart":3558.84}]};
